635	        const errorCode = jsonRpcErrorCode(error);
636	        if (String(message.method || "").startsWith("audio/transcription/")) {
637	          config.statusTracker?.recordTranscriptionError(error, {
638	            subsystem: "transcription",
639	            method: message.method,
640	            code: errorCode,
641	          });
642	        }
643	        config.statusTracker?.recordClientFacingError(error, {
644	          subsystem: errorData?.subsystem || "relay",
645	          method: message.method,
646	          code: errorCode,
647	          retryable: errorData?.retryable,
648	        });
649	        logger.warn("downstream.request_failed", {
650	          subsystem: errorData?.subsystem || "relay",
651	          hostId: config.hostId,
652	          method: message.method,
653	          id: String(message.id),
654	          code: errorCode,
655	          errorData,
656	          durationMs: Date.now() - requestStartedAt,
657	          error,
658	        });
659	        sendJson(
660	          ws,
661	          jsonRpcError(
662	            message.id,
663	            errorCode,
664	            error.message || "relay error",
665	            errorData,
666	          ),
667	        );
668	      }
669	    });
670	  });
671	
672	  const listening = new Promise((resolve) => {
673	    server.listen(config.port, config.listenHost, () => {
674	      const address = server.address();
675	      if (address && typeof address === "object") {
676	        config.port = address.port;
677	      }
678	      advertisement = startBonjourAdvertisement(config);
679	      resolve(address);
680	      logger.info("relay.listening", {
681	        subsystem: "relay",
682	        hostId: config.hostId,
683	        endpointUrl: `ws://${config.listenHost}:${config.port}`,
684	        historyUrl: config.historyUrl,
685	        phoneAuth: config.phoneAuth,
686	      });
687	    });
688	  });
689	
690	  return {
691	    server,
692	    wss,
693	    get advertisement() {
694	      return advertisement;
695	    },
696	    listening,
697	    close: () => new Promise((resolve, reject) => {
698	      logger.info("relay.closing", {
699	        activeConnections: downstreamSockets.size,
700	      });
701	      advertisement?.kill();
702	      for (const ws of downstreamSockets) {
703	        ws.close(1001, "relay shutting down");
704	      }
705	      const forceTerminate = setTimeout(() => {
706	        for (const ws of downstreamSockets) {
707	          ws.terminate();
708	        }
709	      }, 250);
710	      forceTerminate.unref?.();
711	      wss.close(() => {
712	        clearTimeout(forceTerminate);
713	        server.close((error) => {
714	          if (error) {
715	            logger.error("relay.close_failed", { error });
716	            reject(error);
717	          } else {
718	            logger.info("relay.closed");
719	            resolve();
720	          }
721	        });
722	      });
723	    }),
724	  };
725	}
726	
727	function installShutdownHandlers(serverHandle) {
728	  let closing = false;
729	  const closeAndExit = () => {
730	    if (closing) {
731	      return;
732	    }
733	    closing = true;
734	    serverHandle.logger?.info("relay.shutdown_signal");
735	    const forceExit = setTimeout(() => process.exit(0), 1_000);
736	    forceExit.unref();
737	    serverHandle.close()
738	      .then(() => process.exit(0))
739	      .catch(() => process.exit(1));
740	  };
741	
742	  process.once("SIGTERM", closeAndExit);
743	  process.once("SIGINT", closeAndExit);
744	  process.once("exit", () => {
745	    serverHandle.advertisement?.kill();
746	  });
747	}
748	
749	function main() {
750	  installRelayFatalHandlers(defaultRelayLogger);
751	  const args = parseArgs(process.argv.slice(2));
752	  loadDotEnvFile(args["env-file"] || process.env.CODEX_DOCK_ENV_FILE || ".env");
753	  const relayTokenFile = args["auth-token-file"] || process.env.CODEX_DOCK_RELAY_TOKEN_FILE;
754	  const phoneAuth = parsePhoneAuthMode(
755	    args["phone-auth"] || process.env.CODEX_DOCK_PHONE_AUTH || (relayTokenFile ? "bearer" : DEFAULT_PHONE_AUTH),
756	  );
757	  const historyTokenFile = args["history-auth-token-file"] || process.env.CODEX_DOCK_HISTORY_TOKEN_FILE || relayTokenFile;
758	  if (phoneAuth === "bearer" && !relayTokenFile) {
759	    throw new Error("--auth-token-file is required when --phone-auth bearer");
760	  }
761	  if (!historyTokenFile) {
762	    throw new Error("--history-auth-token-file is required");
763	  }
764	
765	  const serverHandle = startServer({
766	    listenHost: args["listen-host"] || process.env.CODEX_DOCK_RELAY_LISTEN_HOST || "0.0.0.0",
767	    port: parseLimit(args.port || process.env.CODEX_DOCK_RELAY_PORT, 4510),
768	    phoneAuth,
769	    relayBearerToken: relayTokenFile ? readToken(relayTokenFile) : null,
770	    historyBearerToken: readToken(historyTokenFile),
771	    historyUrl: args["history-url"] || process.env.CODEX_DOCK_HISTORY_APP_SERVER_WS || "ws://127.0.0.1:4500",
772	    hostId: args["host-id"] || process.env.CODEX_DOCK_REAL_HOST_ID || os.hostname(),
773	    hostName: args["host-name"] || process.env.CODEX_DOCK_REAL_HOST_NAME || args["bonjour-name"],
774	    bonjourName: args["bonjour-name"] || process.env.CODEX_DOCK_BONJOUR_NAME || `Codex Dock ${os.hostname()}`,
775	    advertiseBonjour: (args["advertise-bonjour"] || process.env.CODEX_DOCK_ADVERTISE_BONJOUR || "1") !== "0",
776	    openAIAPIKey: process.env.OPENAI_API_KEY,
777	    openAIRealtimeTranscriptionModel: process.env.CODEX_DOCK_OPENAI_REALTIME_TRANSCRIPTION_MODEL
778	      || DEFAULT_REALTIME_TRANSCRIPTION_MODEL,
779	    openAIRealtimeTranscriptionEndpoint: process.env.CODEX_DOCK_OPENAI_REALTIME_TRANSCRIPTION_ENDPOINT
780	      || DEFAULT_REALTIME_TRANSCRIPTION_ENDPOINT,
781	    realtimeTranscriptionLanguage: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_LANGUAGE
782	      || DEFAULT_REALTIME_TRANSCRIPTION_LANGUAGE,
783	    realtimeTranscriptionDelay: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_DELAY
784	      || DEFAULT_REALTIME_TRANSCRIPTION_DELAY,
785	    realtimeTranscriptionAllowedLanguages: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_ALLOWED_LANGUAGES,
786	    realtimeTranscriptionMaxChunkBytes: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_MAX_CHUNK_BYTES,
787	    realtimeTranscriptionMaxPendingBytes: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_MAX_PENDING_BYTES,
788	    realtimeTranscriptionConnectTimeoutMs: process.env.CODEX_DOCK_OPENAI_REALTIME_TRANSCRIPTION_CONNECT_TIMEOUT_MS,
789	    realtimeTranscriptionMaxDurationMs: process.env.CODEX_DOCK_REALTIME_TRANSCRIPTION_MAX_DURATION_MS,
790	    openAISafetyIdentifier: process.env.CODEX_DOCK_OPENAI_SAFETY_IDENTIFIER,
791	    logger: defaultRelayLogger,
792	  });
793	  serverHandle.logger = defaultRelayLogger;
794	  installShutdownHandlers(serverHandle);
795	}
796	
797	if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
798	  main();
799	}
800	
801	export {
802	  attentionFlagsForServerRequest,
803	  buildBonjourAdvertisementArgs,
804	  isPhoneRequestAuthorized,
805	  loadDotEnvFile,
806	  mergeThreadListRows,
