418	  return withClient(
419	    endpoint.url,
420	    { bearerToken: endpoint.bearerToken || null, logger },
421	    async (client) => client.request("thread/read", params),
422	  );
423	}
424	
425	function sanitizeRelayFields(thread) {
426	  if (!thread || typeof thread !== "object") {
427	    return thread;
428	  }
429	  const { dockRelaySource, ...clean } = thread;
430	  return clean;
431	}
432	
433	function shouldCollectLiveRowsForThreadList(params = {}) {
434	  return params.archived !== true;
435	}
436	
437	function mergeLiveRowWithHistoryFreshness(liveRow, historyRow) {
438	  if (!historyRow) {
439	    return liveRow;
440	  }
441	
442	  const historyTimestamp = rowTimestamp(historyRow);
443	  if (!Number.isFinite(historyTimestamp)) {
444	    return liveRow;
445	  }
446	
447	  const liveTimestamp = rowTimestamp(liveRow);
448	  if (Number.isFinite(liveTimestamp) && historyTimestamp <= liveTimestamp) {
449	    return liveRow;
450	  }
451	
452	  return {
453	    ...liveRow,
454	    updatedAt: historyTimestamp,
455	  };
456	}
457	
458	function mergeThreadListRows(historyRows = [], liveRows = [], params = {}) {
459	  const historyById = new Map();
460	  for (const row of historyRows) {
461	    if (!row?.id) {
462	      continue;
463	    }
464	    const existing = historyById.get(row.id);
465	    if (!existing || rowTimestamp(row) >= rowTimestamp(existing)) {
466	      historyById.set(row.id, row);
467	    }
468	  }
469	  const freshenedLiveRows = liveRows.map((row) => (
470	    mergeLiveRowWithHistoryFreshness(row, historyById.get(row?.id))
471	  ));
472	  const liveIds = new Set(freshenedLiveRows.map((row) => row.id));
473	  const sortRows = (rows) => [...rows].sort((lhs, rhs) => {
474	    const timestampDelta = rowTimestamp(rhs) - rowTimestamp(lhs);
475	    if (timestampDelta !== 0) {
476	      return timestampDelta;
477	    }
478	    const statusDelta = statusPriority(lhs) - statusPriority(rhs);
479	    if (statusDelta !== 0) {
480	      return statusDelta;
481	    }
482	    return String(lhs.id || "").localeCompare(String(rhs.id || ""));
483	  });
484	
485	  const sortedLiveRows = sortRows(freshenedLiveRows.map(sanitizeRelayFields));
486	  const historyOnlyRows = sortRows(historyRows.filter((row) => !liveIds.has(row.id)));
487	  const limit = parseLimit(params.limit, sortedLiveRows.length + historyOnlyRows.length || 1);
488	  return [
489	    ...sortedLiveRows.slice(0, limit),
490	    ...historyOnlyRows.slice(0, Math.max(0, limit - sortedLiveRows.length)),
491	  ];
492	}
493	
494	async function enrichThreadListPreviews(config, rows, endpointByThreadId = new Map()) {
495	  const logger = relayLogger(config);
496	  return mapWithConcurrency(
497	    rows,
498	    THREAD_LIST_PREVIEW_ENRICH_CONCURRENCY,
499	    async (row) => {
500	      if (!row?.id) {
501	        return row;
502	      }
503	      const endpoint = endpointByThreadId.get(row.id) || {
504	        url: config.historyUrl,
505	        bearerToken: config.historyBearerToken,
506	      };
507	      try {
508	        const turns = await readThreadTurnsFromEndpoint(endpoint, {
509	          threadId: row.id,
510	          limit: THREAD_LIST_PREVIEW_TURNS_LIMIT,
511	        }, THREAD_LIST_PREVIEW_ENRICH_TIMEOUT_MS, logger);
512	        const preview = latestMeaningfulTextFromTurns(turns?.data);
513	        if (!preview) {
514	          return row;
515	        }
516	        return {
517	          ...row,
518	          preview,
519	        };
520	      } catch (error) {
521	        logger.warn("thread_list.preview_enrich_failed", {
522	          threadId: row.id,
523	          endpointUrl: endpoint.url,
524	          error,
525	        });
526	        return row;
527	      }
528	    },
529	  );
530	}
531	
532	async function aggregateThreadList(config, params = {}) {
533	  const logger = relayLogger(config);
534	  if (!shouldCollectLiveRowsForThreadList(params)) {
535	    const history = await readHistoryThreadList(config, params);
536	    const data = await enrichThreadListPreviews(config, history.data || []);
537	    logger.info("thread_list.archived_loaded", {
538	      historyRows: history.data?.length || 0,
539	      liveRows: 0,
540	      returnedRows: data.length,
541	    });
542	    return {
543	      ...history,
544	      data,
545	    };
546	  }
547	
548	  const [historyResult, liveResult] = await Promise.allSettled([
549	    readHistoryThreadList(config, params),
550	    collectLiveRows(logger),
551	  ]);
552	  if (historyResult.status === "rejected" && liveResult.status === "rejected") {
553	    throw new Error(
554	      `thread/list failed for history and live sources: history=${historyResult.reason?.message || historyResult.reason}; live=${liveResult.reason?.message || liveResult.reason}`,
555	    );
556	  }
557	
558	  const history = historyResult.status === "fulfilled"
559	    ? historyResult.value
560	    : { data: [] };
561	  const live = liveResult.status === "fulfilled"
562	    ? liveResult.value
563	    : { endpoints: [], failedEndpoints: 1, rows: [] };
564	
565	  if (historyResult.status === "rejected") {
566	    logger.warn("thread_list.history_failed", {
567	      error: historyResult.reason,
568	    });
569	  }
570	  if (liveResult.status === "rejected") {
571	    logger.warn("thread_list.live_failed", {
572	      error: liveResult.reason,
573	    });
574	  }
575	
576	  const filteredLiveRows = live.rows.filter((row) => (
577	    threadMatchesSourceKinds(row, params.sourceKinds)
578	  ));
579	  const endpointByThreadId = new Map(
580	    filteredLiveRows
581	      .filter((row) => row?.id && row.dockRelaySource)
582	      .map((row) => [row.id, row.dockRelaySource]),
583	  );
584	  const data = await enrichThreadListPreviews(
585	    config,
586	    mergeThreadListRows(history.data || [], filteredLiveRows, params),
587	    endpointByThreadId,
588	  );
589	  logger.info("thread_list.loaded", {
590	    historyRows: history.data?.length || 0,
591	    liveRows: filteredLiveRows.length,
592	    endpoints: live.endpoints.length,
593	    failedEndpoints: live.failedEndpoints,
594	    returnedRows: data.length,
595	  });
596	  return {
597	    data,
598	    nextCursor: null,
599	    backwardsCursor: null,
600	  };
601	}
602	
603	async function aggregateLoadedList(params = {}, logger = defaultRelayLogger) {
604	  const live = await collectLiveRows(logger);
605	  const ids = live.rows.map((row) => row.id);
606	  logger.info("thread_loaded_list.loaded", {
607	    liveRows: ids.length,
608	    endpoints: live.endpoints.length,
609	    failedEndpoints: live.failedEndpoints,
610	  });
611	  return paginateStrings(ids, params);
612	}
613	
614	async function aggregateThreadRead(config, params = {}) {
615	  if (!params.threadId) {
616	    throw new Error("thread/read requires threadId");
617	  }
618	  const live = await collectLiveRows(relayLogger(config));
619	  const liveRow = live.rows.find((row) => row.id === params.threadId);
620	  if (liveRow) {
621	    if (params.includeTurns) {
622	      return readThreadFromEndpoint(liveRow.dockRelaySource, params, relayLogger(config));
623	    }
624	    return { thread: sanitizeRelayFields(liveRow) };
625	  }
626	  return readHistoryThread(config, params);
627	}
628	
629	async function listThreadTurns(config, params = {}) {
