639	  const liveRow = live.rows.find((row) => row.id === threadId);
640	  if (liveRow?.dockRelaySource) {
641	    return liveRow.dockRelaySource;
642	  }
643	  return {
644	    url: config.historyUrl,
645	    bearerToken: config.historyBearerToken,
646	  };
647	}
