649	async function archiveThread(config, params = {}) {
650	  if (!params.threadId) {
651	    throw new Error("thread/archive requires threadId");
652	  }
653	  const endpoint = await endpointForThread(config, params.threadId);
654	  return withClient(
655	    endpoint.url,
656	    { bearerToken: endpoint.bearerToken || null, logger: relayLogger(config) },
657	    async (client) => client.request("thread/archive", params),
658	  );
