664	  }
665	  return withClient(
666	    config.historyUrl,
667	    { bearerToken: config.historyBearerToken, logger: relayLogger(config) },
668	    async (client) => client.request("thread/unarchive", params),
669	  );
670	}
671	
672	export {
673	  aggregateLoadedList,
674	  aggregateThreadList,
675	  aggregateThreadRead,
