    case offline(String)
    case error(String)

    public var subtitle: String {
        switch self {
        case .loaded(let rowCount):
            return "\(rowCount) sessions"
        case .partial(let rowCount, let message):
            return "\(rowCount) sessions, partial: \(message)"
        case .empty:
            return "Online, no sessions"
        case .offline:
            return "Offline"
        case .error:
            return "Error"
        }
