4	public enum RelayBootstrapState: Equatable, Sendable {
5	    case starting
6	    case discovering(relays: [DiscoveredRelay], message: String?)
7	    case ready(HostRegistry)
8	    case failed(String)
9	}
10	
11	@MainActor
12	public final class RelayBootstrapStore: ObservableObject {
13	    @Published public private(set) var state: RelayBootstrapState = .starting
14	    @Published public var manualHostText = ""
15	    @Published public var manualPortText = "4510"
16	
17	    private let environment: [String: String]
18	    private let configurationStore: any LocalDockConfigurationStoring
19	    private let discovery: any RelayDiscoveryManaging
20	    private var didStart = false
21	    private var didBindDiscoveryCallback = false
22	    private var isBackgrounded = false
23	    private var isDiscoveryRunning = false
24	    private var isLoadingSavedConfiguration = false
25	    private var isUsingConfiguration = false
26	    private var handledResumeGeneration: Int?
27	
28	    public init(
29	        environment: [String: String] = ProcessInfo.processInfo.environment,
30	        configurationStore: any LocalDockConfigurationStoring = FileLocalDockConfigurationStore(),
31	        discovery: any RelayDiscoveryManaging = BonjourRelayDiscovery()
32	    ) {
33	        self.environment = environment
34	        self.configurationStore = configurationStore
35	        self.discovery = discovery
36	    }
37	
38	    public func start() {
39	        guard !didStart else {
40	            DockLog.bootstrap.debug("relay bootstrap start skipped reason=already_started")
41	            return
42	        }
43	        didStart = true
44	        DockLog.bootstrap.notice("relay bootstrap started")
45	
46	        if let registry = try? HostRegistry.fromEnvironment(environment) {
47	            DockLog.bootstrap.notice("relay bootstrap environment ready hosts=\(registry.hosts.count, privacy: .public)")
48	            state = .ready(registry)
49	            startDiscoveryIfNeeded(message: "Finding Codex Dock relay", preserveReadyState: true)
50	            Task {
51	                await loadSavedManualURL(allowManualTextOverwrite: true)
52	            }
53	            return
54	        }
55	        DockLog.bootstrap.info("relay bootstrap environment missing; starting discovery")
56	
57	        isLoadingSavedConfiguration = true
58	        startDiscoveryIfNeeded(message: "Finding Codex Dock relay")
59	
60	        Task {
61	            await loadSavedManualURL(allowManualTextOverwrite: true)
62	        }
63	    }
64	
65	    public func handleLifecycle(_ snapshot: AppLifecycleSnapshot) {
66	        DockLog.bootstrap.debug("relay bootstrap lifecycle phase=\(snapshot.phase.logDescription, privacy: .public) resume_generation=\(snapshot.resumeGeneration, privacy: .public)")
67	        switch snapshot.phase {
68	        case .inactive:
69	            return
70	        case .backgrounded:
71	            isBackgrounded = true
72	            guard !isReady else {
73	                return
74	            }
75	            stopDiscoveryIfNeeded()
76	            state = .discovering(relays: discovery.relays, message: "Backgrounded")
77	        case .foregroundResuming:
78	            guard handledResumeGeneration != snapshot.resumeGeneration else {
79	                return
80	            }
81	            handledResumeGeneration = snapshot.resumeGeneration
82	            isBackgrounded = false
83	            guard !isReady else {
84	                return
85	            }
86	            startDiscoveryIfNeeded(message: "Finding Codex Dock relay")
87	            Task {
88	                await loadSavedManualURL(allowManualTextOverwrite: false)
89	            }
90	        case .active:
91	            isBackgrounded = false
92	        }
93	    }
94	
95	    public func connectManually() async {
96	        do {
97	            let endpoint = try Self.validatedEndpoint(host: manualHostText, port: manualPortText)
98	            DockLog.bootstrap.notice("relay manual connect started endpoint=\(DockLog.endpoint(endpoint.webSocketURL), privacy: .public)")
99	            await useEndpoint(endpoint)
100	        } catch {
101	            DockLog.bootstrap.error("relay manual connect failed error=\(DockLog.errorSummary(error), privacy: .public)")
102	            state = .discovering(relays: discovery.relays, message: error.localizedDescription)
103	        }
104	    }
105	
106	    public func use(_ relay: DiscoveredRelay) async {
107	        DockLog.bootstrap.notice("relay discovery selection started relay_id=\(relay.id, privacy: .public) name=\(relay.displayName, privacy: .public)")
108	        await useEndpoint(relay.endpoint)
109	    }
110	
111	    nonisolated public static func validatedEndpoint(host: String, port: String) throws -> DockRelayEndpoint {
112	        guard let portNumber = Int(port.trimmingCharacters(in: .whitespacesAndNewlines)) else {
113	            throw DockHostConfigurationError.invalidPort(port)
114	        }
115	        return try DockRelayEndpoint(host: host, port: portNumber)
116	    }
117	
118	    private func handleDiscoveredRelays(_ relays: [DiscoveredRelay]) {
119	        DockLog.bootstrap.debug("relay discovery updated count=\(relays.count, privacy: .public) backgrounded=\(self.isBackgrounded, privacy: .public) running=\(self.isDiscoveryRunning, privacy: .public)")
120	        guard !isBackgrounded, isDiscoveryRunning else {
121	            guard !isReady else {
122	                return
123	            }
124	            state = .discovering(
125	                relays: relays,
126	                message: isBackgrounded ? "Backgrounded" : "Finding Codex Dock relay"
127	            )
128	            return
129	        }
130	
131	        guard !isLoadingSavedConfiguration else {
132	            state = .discovering(relays: relays, message: "Finding Codex Dock relay")
133	            return
134	        }
135	
136	        if case .ready(let registry) = state {
137	            Task {
138	                await upsert(relays.map(\.endpoint), into: registry)
139	            }
140	            return
141	        }
142	
143	        guard case .ready = state else {
144	            if let first = relays.first {
145	                Task {
146	                    await use(first)
147	                }
148	            } else {
149	                state = .discovering(relays: relays, message: "Finding Codex Dock relay")
150	            }
151	            return
152	        }
153	    }
154	
155	    private var isReady: Bool {
156	        if case .ready = state {
157	            return true
158	        }
159	        return false
160	    }
161	
162	    private func bindDiscoveryCallbackIfNeeded() {
163	        guard !didBindDiscoveryCallback else {
164	            return
165	        }
166	        didBindDiscoveryCallback = true
