821	}
822	
823	async function statusHostServices(config, runtime = {}) {
824	  const services = await serviceState(config, runtime);
825	  const health = [
826	    await checkHealth("raw-app-server-readyz", httpURLForWebSocket(config.appServer.listenURL, "/readyz"), runtime),
827	    await checkHealth("relay-readyz", localRelayHTTPURL(config, "/readyz"), runtime),
828	    await checkRelayStatusz("relay-statusz", localRelayHTTPURL(config, "/statusz"), runtime),
829	  ];
830	  if (config.network.profile !== "simulator-local") {
831	    health.push(await checkHealth("relay-app-facing-readyz", httpURLForWebSocket(config.relay.publicURL, "/readyz"), runtime));
832	  }
833	  const ready = services.every((service) => service.active) && health.every((entry) => entry.ok);
834	  return redactValue({
835	    version: 1,
836	    status: ready ? "ready" : "not-ready",
837	    checked: true,
838	    host: {
839	      id: config.host.id,
840	      displayName: config.host.displayName,
841	    },
842	    serviceManager: config.serviceManager,
843	    appEndpoint: {
844	      host: config.relay.appEndpoint.host,
845	      port: config.relay.appEndpoint.port,
846	    },
847	    services,
848	    health,
849	  });
850	}
851	
852	async function logsHostServices(config, runtime = {}) {
853	  if (config.platform === "linux") {
854	    const commands = [];
855	    for (const service of serviceEntries(config)) {
856	      const result = await commandRunner(runtime)("journalctl", ["--user", "-u", service.unit, "-n", "200", "--no-pager"], { cwd: config.cwd, env: serviceCommandEnv(runtime) });
857	      commands.push({
858	        role: service.role,
859	        exitCode: result.exitCode,
860	        stdout: redactValue(tailText(result.stdout, 200), "log"),
861	        stderr: redactValue(tailText(result.stderr, 40), "log"),
862	      });
863	    }
864	    return { version: 1, serviceManager: config.serviceManager, logs: commands };
865	  }
866	  return {
867	    version: 1,
868	    serviceManager: config.serviceManager,
869	    logs: serviceEntries(config).map((service) => ({
870	      role: service.role,
871	      stdout: redactValue(tailText(readTextIfExists(service.stdoutLog), 200), "log"),
872	      stderr: redactValue(tailText(readTextIfExists(service.stderrLog), 200), "log"),
873	    })),
874	  };
875	}
876	
877	async function doctorHostServices(config, runtime = {}) {
878	  const status = await statusHostServices(config, runtime);
879	  const problems = [];
880	  for (const service of status.services) {
881	    if (!service.active) {
882	      problems.push(`${service.role} service is not active`);
883	    }
884	  }
885	  for (const health of status.health) {
886	    if (!health.ok) {
887	      problems.push(`${health.name} is not healthy`);
888	    }
889	  }
890	  return redactValue({
891	    version: 1,
892	    status: problems.length ? "failed" : "passed",
893	    problems,
894	    checks: status,
895	  });
896	}
897	
898	function renderText(files) {
899	  return files.map((file) => [
900	    `# ${file.role}: ${file.path}`,
901	    file.contents,
902	  ].join("\n")).join("\n");
903	}
904	
905	async function main(argv = process.argv.slice(2), io = { stdout: process.stdout, stderr: process.stderr }, runtime = {}) {
906	  const { args, positionals } = parseArgs(argv);
907	  const command = positionals[0] || args.command;
908	  if (!command || args.help) {
909	    io.stdout.write(`${usage()}\n`);
910	    return 0;
911	  }
912	  if (!COMMANDS.has(command)) {
913	    throw new Error(`unknown command: ${command}`);
914	  }
915	
916	  const config = createHostServiceConfig({
917	    options: args,
918	    env: runtime.env || process.env,
919	    cwd: runtime.cwd || process.cwd(),
920	    platform: runtime.platform || process.platform,
921	  });
922	  switch (command) {
923	  case "render": {
924	    const format = args.format || "text";
925	    const files = renderHostServices(config);
926	    if (format === "json") {
927	      io.stdout.write(`${JSON.stringify({ version: 1, config: redactValue(config), files }, null, 2)}\n`);
928	    } else if (format === "text") {
929	      io.stdout.write(renderText(files));
930	    } else {
931	      throw new Error("render format must be json or text");
932	    }
933	    return 0;
934	  }
935	  case "app-config": {
936	    const format = args.format || "json";
937	    if (format === "json") {
938	      io.stdout.write(`${JSON.stringify(appConfigJSON(config), null, 2)}\n`);
939	    } else if (format === "env") {
940	      io.stdout.write(appConfigEnv(config));
941	    } else {
942	      throw new Error("app-config format must be json or env");
943	    }
944	    return 0;
945	  }
946	  case "status":
947	  {
948	    const status = await statusHostServices(config, runtime);
949	    io.stdout.write(`${JSON.stringify(status, null, 2)}\n`);
950	    return status.status === "ready" ? 0 : 1;
951	  }
952	  case "install":
953	    io.stdout.write(`${JSON.stringify(await installHostServices(config, runtime), null, 2)}\n`);
954	    return 0;
955	  case "start":
956	  case "stop":
957	  case "restart":
958	    io.stdout.write(`${JSON.stringify(await manageHostServices(config, command, runtime), null, 2)}\n`);
959	    return 0;
960	  case "logs":
961	    io.stdout.write(`${JSON.stringify(await logsHostServices(config, runtime), null, 2)}\n`);
962	    return 0;
963	  case "doctor":
964	  {
965	    const result = await doctorHostServices(config, runtime);
966	    io.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
967	    return result.status === "passed" ? 0 : 1;
968	  }
969	  }
970	}
971	
972	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
973	  main().then((code) => {
974	    process.exitCode = code;
975	  }).catch((error) => {
976	    process.stderr.write(`${redactValue(error.message)}\n\n${usage()}\n`);
977	    process.exitCode = 2;
978	  });
979	}
980	
981	export {
982	  appConfigEnv,
983	  appConfigJSON,
984	  createHostServiceConfig,
985	  dryRunStatus,
986	  doctorHostServices,
987	  hostIDToEnvSuffix,
988	  installHostServices,
989	  logsHostServices,
990	  main,
991	  manageHostServices,
992	  redactValue,
993	  renderHostServices,
994	  resolveRelayPublicURL,
995	  statusHostServices,
996	  validateWebSocketURL,
997	};
998

