130	/// Control-plane messages from the processor/transport side to the outbound router task.
131	///
132	/// `run_main_with_transport_options` uses two loops/tasks:
133	/// - processor loop: handles incoming JSON-RPC and request dispatch
134	/// - outbound loop: performs potentially slow writes to per-connection writers
135	///
136	/// `OutboundControlEvent` keeps those loops coordinated without sharing mutable
137	/// connection state directly. In particular, the outbound loop needs to know
138	/// when a connection opens/closes so it can route messages correctly.
139	enum OutboundControlEvent {
140	    /// Register a new writer for an opened connection.
141	    Opened {
142	        connection_id: ConnectionId,
143	        writer: mpsc::Sender<QueuedOutgoingMessage>,
144	        disconnect_sender: Option<CancellationToken>,
145	        initialized: Arc<AtomicBool>,
146	        experimental_api_enabled: Arc<AtomicBool>,
147	        opted_out_notification_methods: Arc<RwLock<HashSet<String>>>,
148	    },
149	    /// Remove state for a closed/disconnected connection.
150	    Closed { connection_id: ConnectionId },
151	    /// Disconnect all connection-oriented clients during graceful restart.
152	    DisconnectAll,
153	}
