155	#[derive(Default)]
156	struct ShutdownState {
157	    requested: bool,
158	    forced: bool,
159	    last_logged_running_turn_count: Option<usize>,
160	}
161	
162	enum ShutdownAction {
163	    Noop,
164	    Finish,
165	}
166	
167	#[derive(Clone, Copy)]
168	enum ShutdownSignal {
169	    Forceable,
170	    #[cfg(unix)]
171	    GracefulOnly,
172	}
173	
174	async fn shutdown_signal() -> IoResult<ShutdownSignal> {
175	    #[cfg(unix)]
176	    {
177	        use tokio::signal::unix::SignalKind;
178	        use tokio::signal::unix::signal;
179	
180	        let mut term = signal(SignalKind::terminate())?;
181	        let mut hangup = signal(SignalKind::hangup())?;
182	        tokio::select! {
183	            ctrl_c_result = tokio::signal::ctrl_c() => ctrl_c_result.map(|_| ShutdownSignal::Forceable),
184	            _ = term.recv() => Ok(ShutdownSignal::Forceable),
185	            _ = hangup.recv() => Ok(ShutdownSignal::GracefulOnly),
186	        }
187	    }
188	
189	    #[cfg(not(unix))]
190	    {
191	        tokio::signal::ctrl_c()
192	            .await
193	            .map(|_| ShutdownSignal::Forceable)
194	    }
195	}
196	
197	impl ShutdownState {
198	    fn requested(&self) -> bool {
199	        self.requested
200	    }
201	
202	    fn forced(&self) -> bool {
203	        self.forced
204	    }
205	
206	    fn on_signal(
207	        &mut self,
208	        signal: ShutdownSignal,
209	        connection_count: usize,
210	        running_turn_count: usize,
211	    ) {
212	        if self.requested {
213	            if matches!(signal, ShutdownSignal::Forceable) {
214	                self.forced = true;
215	            }
216	            return;
217	        }
218	
219	        self.requested = true;
220	        self.last_logged_running_turn_count = None;
221	        info!(
222	            "received shutdown signal; entering graceful restart drain (connections={}, runningAssistantTurns={}, requests still accepted until no assistant turns are running)",
223	            connection_count, running_turn_count,
224	        );
225	    }
226	
227	    fn update(&mut self, running_turn_count: usize, connection_count: usize) -> ShutdownAction {
228	        if !self.requested {
229	            return ShutdownAction::Noop;
230	        }
231	
232	        if self.forced || running_turn_count == 0 {
233	            if self.forced {
234	                info!(
235	                    "received second shutdown signal; forcing restart with {running_turn_count} running assistant turn(s) and {connection_count} connection(s)"
236	                );
237	            } else {
238	                info!(
239	                    "shutdown signal restart: no assistant turns running; stopping acceptor and disconnecting {connection_count} connection(s)"
240	                );
241	            }
242	            return ShutdownAction::Finish;
243	        }
244	
245	        if self.last_logged_running_turn_count != Some(running_turn_count) {
246	            info!(
247	                "shutdown signal restart: waiting for {running_turn_count} running assistant turn(s) to finish"
248	            );
249	            self.last_logged_running_turn_count = Some(running_turn_count);
250	        }
251	
252	        ShutdownAction::Noop
253	    }
254	}
