272	fn config_error_location(err: &std::io::Error) -> Option<(String, AppTextRange)> {
273	    err.get_ref()
274	        .and_then(|err| err.downcast_ref::<ConfigLoadError>())
275	        .map(|err| {
276	            let config_error = err.config_error();
277	            (
278	                config_error.path.to_string_lossy().to_string(),
279	                app_text_range(&config_error.range),
280	            )
281	        })
282	}
