284	fn exec_policy_warning_location(err: &ExecPolicyError) -> (Option<String>, Option<AppTextRange>) {
285	    match err {
286	        ExecPolicyError::ParsePolicy { path, source } => {
287	            if let Some(location) = source.location() {
288	                let range = AppTextRange {
289	                    start: AppTextPosition {
290	                        line: location.range.start.line,
291	                        column: location.range.start.column,
292	                    },
293	                    end: AppTextPosition {
294	                        line: location.range.end.line,
295	                        column: location.range.end.column,
296	                    },
297	                };
298	                return (Some(location.path), Some(range));
299	            }
300	            (Some(path.clone()), None)
301	        }
302	        _ => (None, None),
303	    }
304	}
