319	fn project_config_warning(config: &Config) -> Option<ConfigWarningNotification> {
320	    let mut disabled_folders = Vec::new();
321	
322	    for layer in config.config_layer_stack.get_layers(
323	        ConfigLayerStackOrdering::LowestPrecedenceFirst,
324	        /*include_disabled*/ true,
325	    ) {
326	        let ConfigLayerSource::Project { dot_codex_folder } = &layer.name else {
327	            continue;
328	        };
329	        let Some(disabled_reason) = &layer.disabled_reason else {
330	            continue;
331	        };
332	        disabled_folders.push((
333	            dot_codex_folder.as_path().display().to_string(),
334	            disabled_reason.clone(),
335	        ));
336	    }
337	
338	    if disabled_folders.is_empty() {
339	        return None;
340	    }
341	
342	    let mut message = concat!(
343	        "Project-local config, hooks, and exec policies are disabled in the following folders ",
344	        "until the project is trusted, but skills still load.\n",
345	    )
346	    .to_string();
347	    for (index, (folder, reason)) in disabled_folders.iter().enumerate() {
348	        let display_index = index + 1;
349	        message.push_str(&format!("    {display_index}. {folder}\n"));
350	        message.push_str(&format!("       {reason}\n"));
351	    }
352	
353	    Some(ConfigWarningNotification {
354	        summary: message,
355	        details: None,
356	        path: None,
357	        range: None,
358	    })
359	}
