420	pub async fn run_main_with_transport_options(
421	    arg0_paths: Arg0DispatchPaths,
422	    cli_config_overrides: CliConfigOverrides,
423	    loader_overrides: LoaderOverrides,
424	    strict_config: bool,
425	    default_analytics_enabled: bool,
426	    transport: AppServerTransport,
427	    session_source: SessionSource,
428	    auth: AppServerWebsocketAuthSettings,
429	    runtime_options: AppServerRuntimeOptions,
430	) -> IoResult<()> {
431	    let (transport_event_tx, mut transport_event_rx) =
432	        mpsc::channel::<TransportEvent>(CHANNEL_CAPACITY);
433	    let (outgoing_tx, mut outgoing_rx) = mpsc::channel::<OutgoingEnvelope>(CHANNEL_CAPACITY);
434	    let (outbound_control_tx, mut outbound_control_rx) =
435	        mpsc::channel::<OutboundControlEvent>(CHANNEL_CAPACITY);
436	
437	    // Parse CLI overrides once and derive the base Config eagerly so later
438	    // components do not need to work with raw TOML values.
439	    let cli_kv_overrides = cli_config_overrides.parse_overrides().map_err(|e| {
440	        std::io::Error::new(
441	            ErrorKind::InvalidInput,
442	            format!("error parsing -c overrides: {e}"),
443	        )
444	    })?;
445	    let codex_home = find_codex_home()?;
446	    let local_runtime_paths = ExecServerRuntimePaths::from_optional_paths(
447	        arg0_paths.codex_self_exe.clone(),
448	        arg0_paths.codex_linux_sandbox_exe.clone(),
449	    )?;
450	    let environment_manager = if loader_overrides.ignore_user_config {
451	        EnvironmentManager::from_env(Some(local_runtime_paths)).await
452	    } else {
453	        EnvironmentManager::from_codex_home(codex_home.clone(), Some(local_runtime_paths)).await
454	    }
455	    .map(Arc::new)
456	    .map_err(std::io::Error::other)?;
457	    let config_manager = ConfigManager::new(
458	        codex_home.to_path_buf(),
459	        cli_kv_overrides.clone(),
460	        loader_overrides,
461	        strict_config,
462	        Default::default(),
463	        arg0_paths.clone(),
464	        Arc::new(NoopThreadConfigLoader),
465	    );
466	    match config_manager
467	        .load_latest_config(/*fallback_cwd*/ None)
468	        .await
469	    {
470	        Ok(config) => {
471	            let discovered_thread_config_loader = configured_thread_config_loader(&config);
472	            config_manager
473	                .replace_thread_config_loader(Arc::clone(&discovered_thread_config_loader));
474	            let auth_manager =
475	                AuthManager::shared_from_config(&config, /*enable_codex_api_key_env*/ false).await;
476	            config_manager.replace_cloud_requirements_loader(auth_manager, config.chatgpt_base_url);
477	        }
478	        Err(err) => {
479	            warn!(error = %err, "Failed to preload config for cloud requirements");
480	            // TODO(gt): Make cloud requirements preload failures blocking once we can fail-closed.
481	        }
482	    };
483	    let mut config_warnings = Vec::new();
484	    let (mut config, should_run_personality_migration) = match config_manager
485	        .load_latest_config(/*fallback_cwd*/ None)
486	        .await
487	    {
488	        Ok(config) => (config, true),
489	        Err(err) => {
490	            if strict_config {
491	                return Err(err);
492	            }
493	
494	            let message = config_warning_from_error("Invalid configuration; using defaults.", &err);
495	            config_warnings.push(message);
496	            (
497	                config_manager.load_default_config().await.map_err(|e| {
498	                    std::io::Error::new(
499	                        ErrorKind::InvalidData,
500	                        format!("error loading default config after config error: {e}"),
501	                    )
502	                })?,
503	                false,
504	            )
505	        }
506	    };
507	
508	    let otel = codex_core::otel_init::build_provider(
509	        &config,
510	        env!("CARGO_PKG_VERSION"),
511	        Some(OTEL_SERVICE_NAME),
512	        default_analytics_enabled,
513	    )
514	    .map_err(|e| {
515	        std::io::Error::new(
516	            ErrorKind::InvalidData,
517	            format!("error loading otel config: {e}"),
518	        )
519	    })?;
520	    codex_core::otel_init::record_process_start(otel.as_ref(), OTEL_SERVICE_NAME);
521	    codex_core::otel_init::install_sqlite_telemetry(otel.as_ref(), OTEL_SERVICE_NAME);
522	    let unix_socket_startup_lock = match &transport {
523	        AppServerTransport::UnixSocket { socket_path } => {
524	            let startup_lock_path = app_server_startup_lock_path(&codex_home)?;
525	            let startup_lock = acquire_app_server_startup_lock(startup_lock_path).await?;
526	            prepare_control_socket_path(socket_path.as_path()).await?;
527	            Some(startup_lock)
528	        }
529	        _ => None,
530	    };
531	    let state_db = match rollout_state_db::try_init(&config).await {
532	        Ok(state_db) => Some(state_db),
533	        Err(err) => {
534	            return Err(std::io::Error::other(format!(
535	                "failed to initialize sqlite state runtime under {}: {err}",
536	                config.sqlite_home.display()
537	            )));
538	        }
539	    };
540	
541	    if should_run_personality_migration {
542	        let effective_toml = config.config_layer_stack.effective_config();
543	        match effective_toml.try_into() {
544	            Ok(config_toml) => {
545	                match codex_core::personality_migration::maybe_migrate_personality(
546	                    &config.codex_home,
547	                    &config_toml,
548	                    state_db.clone(),
549	                )
550	                .await
551	                {
552	                    Ok(codex_core::personality_migration::PersonalityMigrationStatus::Applied) => {
553	                        config = config_manager
554	                            .load_latest_config(/*fallback_cwd*/ None)
555	                            .await
556	                            .map_err(|err| {
557	                                std::io::Error::new(
558	                                    ErrorKind::InvalidData,
559	                                    format!(
560	                                        "error reloading config after personality migration: {err}"
561	                                    ),
562	                                )
563	                            })?;
564	                    }
565	                    Ok(
566	                        codex_core::personality_migration::PersonalityMigrationStatus::SkippedMarker
567	                        | codex_core::personality_migration::PersonalityMigrationStatus::SkippedExplicitPersonality
568	                        | codex_core::personality_migration::PersonalityMigrationStatus::SkippedNoSessions,
569	                    ) => {}
570	                    Err(err) => {
571	                        warn!(error = %err, "Failed to run personality migration");
572	                    }
573	                }
574	            }
575	            Err(err) => {
576	                warn!(error = %err, "Failed to deserialize config for personality migration");
577	            }
578	        }
579	    }
580	
581	    if let Ok(Some(err)) = check_execpolicy_for_warnings(&config.config_layer_stack).await {
582	        let (path, range) = exec_policy_warning_location(&err);
583	        let message = ConfigWarningNotification {
584	            summary: "Error parsing rules; custom rules not applied.".to_string(),
585	            details: Some(err.to_string()),
586	            path,
587	            range,
588	        };
589	        config_warnings.push(message);
590	    }
591	
592	    if let Some(warning) = project_config_warning(&config) {
593	        config_warnings.push(warning);
594	    }
595	    for warning in &config.startup_warnings {
596	        config_warnings.push(ConfigWarningNotification {
597	            summary: warning.clone(),
598	            details: None,
599	            path: None,
600	            range: None,
601	        });
602	    }
603	    if let Some(warning) =
604	        codex_core::config::system_bwrap_warning(config.permissions.permission_profile())
605	    {
606	        config_warnings.push(ConfigWarningNotification {
607	            summary: warning,
608	            details: None,
609	            path: None,
610	            range: None,
611	        });
612	    }
613	
614	    let feedback = CodexFeedback::new();
615	
616	    // Install a simple subscriber so `tracing` output is visible. Users can
617	    // control the log level with `RUST_LOG` and switch to JSON logs with
618	    // `LOG_FORMAT=json`.
619	    let stderr_fmt: StderrLogLayer = match log_format_from_env() {
620	        LogFormat::Json => tracing_subscriber::fmt::layer()
621	            .json()
622	            .with_writer(std::io::stderr)
623	            .with_span_events(tracing_subscriber::fmt::format::FmtSpan::FULL)
624	            .with_filter(EnvFilter::from_default_env())
625	            .boxed(),
626	        LogFormat::Default => tracing_subscriber::fmt::layer()
627	            .with_writer(std::io::stderr)
628	            .with_span_events(tracing_subscriber::fmt::format::FmtSpan::FULL)
629	            .with_filter(EnvFilter::from_default_env())
630	            .boxed(),
631	    };
632	
633	    let feedback_layer = feedback.logger_layer();
634	    let feedback_metadata_layer = feedback.metadata_layer();
635	    let log_db = state_db.clone().map(log_db::start);
636	    let log_db_layer = log_db
637	        .clone()
638	        .map(|layer| layer.with_filter(Targets::new().with_default(Level::TRACE)));
639	    let otel_logger_layer = otel.as_ref().and_then(|o| o.logger_layer());
640	    let otel_tracing_layer = otel.as_ref().and_then(|o| o.tracing_layer());
641	    let _ = tracing_subscriber::registry()
642	        .with(stderr_fmt)
643	        .with(feedback_layer)
644	        .with(feedback_metadata_layer)
645	        .with(log_db_layer)
646	        .with(otel_logger_layer)
647	        .with(otel_tracing_layer)
648	        .try_init();
649	    for warning in &config_warnings {
650	        match &warning.details {
651	            Some(details) => error!("{} {}", warning.summary, details),
652	            None => error!("{}", warning.summary),
653	        }
654	    }
655	    let installation_id = resolve_installation_id(&config.codex_home).await?;
656	    let transport_shutdown_token = CancellationToken::new();
657	    let mut transport_accept_handles = Vec::<JoinHandle<()>>::new();
658	
659	    let single_client_mode = matches!(&transport, AppServerTransport::Stdio);
660	    let shutdown_when_no_connections = single_client_mode;
661	    let graceful_signal_restart_enabled =
662	        runtime_options.install_shutdown_signal_handler && !single_client_mode;
663	    let mut app_server_client_name_rx = None;
664	
665	    match &transport {
666	        AppServerTransport::Stdio => {
667	            let (stdio_client_name_tx, stdio_client_name_rx) = oneshot::channel::<String>();
668	            app_server_client_name_rx = Some(stdio_client_name_rx);
669	            start_stdio_connection(
670	                transport_event_tx.clone(),
671	                &mut transport_accept_handles,
672	                stdio_client_name_tx,
673	            )
674	            .await?;
675	        }
676	        AppServerTransport::UnixSocket { socket_path } => {
677	            let accept_handle = start_control_socket_acceptor(
678	                socket_path.clone(),
679	                transport_event_tx.clone(),
680	                transport_shutdown_token.clone(),
681	            )
682	            .await?;
683	            transport_accept_handles.push(accept_handle);
684	        }
685	        AppServerTransport::WebSocket { bind_address } => {
686	            let accept_handle = start_websocket_acceptor(
687	                *bind_address,
688	                transport_event_tx.clone(),
689	                transport_shutdown_token.clone(),
690	                policy_from_settings(&auth)?,
691	            )
692	            .await?;
693	            transport_accept_handles.push(accept_handle);
694	        }
695	        AppServerTransport::Off => {}
