89	async fn reject_requests_with_origin_header(
90	    request: Request<Body>,
91	    next: Next,
92	) -> Result<Response, StatusCode> {
93	    if request.headers().contains_key(ORIGIN) {
94	        warn!(
95	            method = %request.method(),
96	            uri = %request.uri(),
97	            "rejecting websocket listener request with Origin header"
98	        );
99	        Err(StatusCode::FORBIDDEN)
100	    } else {
101	        Ok(next.run(request).await)
102	    }
103	}
