105	async fn websocket_upgrade_handler(
106	    websocket: WebSocketUpgrade,
107	    ConnectInfo(peer_addr): ConnectInfo<SocketAddr>,
108	    State(state): State<WebSocketListenerState>,
109	    headers: HeaderMap,
110	) -> impl IntoResponse {
111	    if let Err(err) = authorize_upgrade(&headers, state.auth_policy.as_ref()) {
112	        warn!(
113	            %peer_addr,
114	            message = err.message(),
115	            "rejecting websocket client during upgrade"
116	        );
117	        return (err.status_code(), err.message()).into_response();
118	    }
119	    info!(%peer_addr, "websocket client connected");
120	    websocket
121	        .on_upgrade(move |stream| async move {
122	            let (websocket_writer, websocket_reader) = stream.split();
123	            run_websocket_connection(websocket_writer, websocket_reader, state.transport_event_tx)
124	                .await;
125	        })
126	        .into_response()
127	}
