129	pub async fn start_websocket_acceptor(
130	    bind_address: SocketAddr,
131	    transport_event_tx: mpsc::Sender<TransportEvent>,
132	    shutdown_token: CancellationToken,
133	    auth_policy: WebsocketAuthPolicy,
134	) -> IoResult<JoinHandle<()>> {
135	    if is_unauthenticated_non_loopback_listener(bind_address, &auth_policy) {
136	        return Err(std::io::Error::new(
137	            std::io::ErrorKind::InvalidInput,
138	            format!(
139	                "refusing to start non-loopback websocket listener {bind_address} without auth; configure `--ws-auth capability-token` or `--ws-auth signed-bearer-token`"
140	            ),
141	        ));
142	    }
143	    let listener = TcpListener::bind(bind_address).await?;
144	    let local_addr = listener.local_addr()?;
145	    print_websocket_startup_banner(local_addr);
146	    info!("app-server websocket listening on ws://{local_addr}");
147	
148	    let router = Router::new()
149	        .route("/readyz", get(health_check_handler))
150	        .route("/healthz", get(health_check_handler))
151	        .fallback(any(websocket_upgrade_handler))
152	        .layer(middleware::from_fn(reject_requests_with_origin_header))
153	        .with_state(WebSocketListenerState {
154	            transport_event_tx,
155	            auth_policy: Arc::new(auth_policy),
156	        });
157	    let server = axum::serve(
158	        listener,
159	        router.into_make_service_with_connect_info::<SocketAddr>(),
160	    )
161	    .with_graceful_shutdown(async move {
162	        shutdown_token.cancelled().await;
163	    });
164	    Ok(tokio::spawn(async move {
165	        if let Err(err) = server.await {
166	            error!("websocket acceptor failed: {err}");
167	        }
168	        info!("websocket acceptor shutting down");
169	    }))
170	}
