174	    websocket_reader: impl futures::stream::Stream<Item = Result<M, StreamError>> + Send + 'static,
175	    transport_event_tx: mpsc::Sender<TransportEvent>,
176	) where
177	    M: AppServerWebSocketMessage + Send + 'static,
178	    SinkError: Send + 'static,
179	    StreamError: std::fmt::Display + Send + 'static,
180	{
181	    let connection_id = next_connection_id();
182	    let (writer_tx, writer_rx) =
183	        mpsc::channel::<QueuedOutgoingMessage>(WEBSOCKET_OUTBOUND_CHANNEL_CAPACITY);
184	    let writer_tx_for_reader = writer_tx.clone();
185	    let disconnect_token = CancellationToken::new();
186	    if transport_event_tx
187	        .send(TransportEvent::ConnectionOpened {
188	            connection_id,
189	            origin: ConnectionOrigin::WebSocket,
190	            writer: writer_tx,
191	            disconnect_sender: Some(disconnect_token.clone()),
192	        })
193	        .await
194	        .is_err()
195	    {
196	        return;
197	    }
198	
199	    let (writer_control_tx, writer_control_rx) = mpsc::channel::<M>(CHANNEL_CAPACITY);
200	    let mut outbound_task = tokio::spawn(run_websocket_outbound_loop(
201	        websocket_writer,
202	        writer_rx,
203	        writer_control_rx,
204	        disconnect_token.clone(),
205	    ));
206	    let mut inbound_task = tokio::spawn(run_websocket_inbound_loop(
207	        websocket_reader,
208	        transport_event_tx.clone(),
209	        writer_tx_for_reader,
210	        writer_control_tx,
211	        connection_id,
212	        disconnect_token.clone(),
213	    ));
214	
215	    tokio::select! {
216	        _ = &mut outbound_task => {
217	            disconnect_token.cancel();
218	            inbound_task.abort();
219	        }
220	        _ = &mut inbound_task => {
221	            disconnect_token.cancel();
222	            outbound_task.abort();
223	        }
224	    }
225	
226	    let _ = transport_event_tx
227	        .send(TransportEvent::ConnectionClosed { connection_id })
228	        .await;
229	}
