241	/// sends directly.
242	pub(crate) trait AppServerWebSocketMessage: Sized {
243	    fn text(text: String) -> Self;
244	    fn pong(payload: Bytes) -> Self;
245	    fn into_incoming(self) -> Option<IncomingWebSocketMessage>;
