289	async fn run_websocket_outbound_loop<M, SinkError>(
290	    websocket_writer: impl futures::sink::Sink<M, Error = SinkError> + Send + 'static,
291	    mut writer_rx: mpsc::Receiver<QueuedOutgoingMessage>,
292	    mut writer_control_rx: mpsc::Receiver<M>,
293	    disconnect_token: CancellationToken,
294	) where
295	    M: AppServerWebSocketMessage + Send + 'static,
296	    SinkError: Send + 'static,
297	{
298	    tokio::pin!(websocket_writer);
299	    loop {
300	        tokio::select! {
301	            _ = disconnect_token.cancelled() => {
302	                break;
303	            }
304	            message = writer_control_rx.recv() => {
305	                let Some(message) = message else {
306	                    break;
307	                };
308	                if websocket_writer.send(message).await.is_err() {
309	                    break;
310	                }
311	            }
312	            queued_message = writer_rx.recv() => {
313	                let Some(queued_message) = queued_message else {
314	                    break;
315	                };
316	                let Some(json) = serialize_outgoing_message(queued_message.message) else {
317	                    continue;
318	                };
319	                if websocket_writer.send(M::text(json)).await.is_err() {
320	                    break;
321	                }
322	                if let Some(write_complete_tx) = queued_message.write_complete_tx {
323	                    let _ = write_complete_tx.send(());
324	                }
325	            }
326	        }
327	    }
328	}
329	
330	async fn run_websocket_inbound_loop<M, StreamError>(
331	    websocket_reader: impl futures::stream::Stream<Item = Result<M, StreamError>> + Send + 'static,
332	    transport_event_tx: mpsc::Sender<TransportEvent>,
333	    writer_tx_for_reader: mpsc::Sender<QueuedOutgoingMessage>,
334	    writer_control_tx: mpsc::Sender<M>,
335	    connection_id: ConnectionId,
336	    disconnect_token: CancellationToken,
337	) where
338	    M: AppServerWebSocketMessage + Send + 'static,
339	    StreamError: std::fmt::Display + Send + 'static,
340	{
341	    tokio::pin!(websocket_reader);
342	    loop {
343	        tokio::select! {
344	            _ = disconnect_token.cancelled() => {
345	                break;
346	            }
347	            incoming_message = websocket_reader.next() => {
348	                match incoming_message {
349	                    Some(Ok(message)) => match message.into_incoming() {
350	                        Some(IncomingWebSocketMessage::Text(text))
351	                            if !forward_incoming_message(
352	                                &transport_event_tx,
353	                                &writer_tx_for_reader,
354	                                connection_id,
355	                                &text,
356	                            )
357	                            .await
358	                        => {
359	                            break;
360	                        }
361	                        Some(IncomingWebSocketMessage::Text(_)) => {}
362	                        Some(IncomingWebSocketMessage::Ping(payload)) => {
363	                            match writer_control_tx.try_send(M::pong(payload)) {
364	                                Ok(()) => {}
365	                                Err(tokio::sync::mpsc::error::TrySendError::Closed(_)) => break,
366	                                Err(tokio::sync::mpsc::error::TrySendError::Full(_)) => {
367	                                    warn!("websocket control queue full while replying to ping; closing connection");
368	                                    break;
369	                                }
370	                            }
371	                        }
372	                        Some(IncomingWebSocketMessage::Pong) => {}
373	                        Some(IncomingWebSocketMessage::Close) => break,
374	                        Some(IncomingWebSocketMessage::Binary) => {
375	                            warn!("dropping unsupported binary websocket message");
376	                        }
377	                        None => {}
378	                    },
379	                    None => break,
380	                    Some(Err(err)) => {
381	                        warn!("websocket receive error: {err}");
382	                        break;
383	                    }
384	                }
385	            }
386	        }
387	    }
388	}
