138	    pub fn try_into_settings(self) -> anyhow::Result<AppServerWebsocketAuthSettings> {
139	        let normalize = |value: Option<String>| {
140	            value.and_then(|value| {
141	                let trimmed = value.trim();
142	                (!trimmed.is_empty()).then(|| trimmed.to_string())
143	            })
144	        };
145	
146	        let config = match self.ws_auth {
147	            Some(WebsocketAuthCliMode::CapabilityToken) => {
148	                if self.ws_shared_secret_file.is_some()
149	                    || self.ws_issuer.is_some()
150	                    || self.ws_audience.is_some()
151	                    || self.ws_max_clock_skew_seconds.is_some()
152	                {
153	                    anyhow::bail!(
154	                        "`--ws-shared-secret-file`, `--ws-issuer`, `--ws-audience`, and `--ws-max-clock-skew-seconds` require `--ws-auth signed-bearer-token`"
155	                    );
156	                }
157	                let source = match (self.ws_token_file, self.ws_token_sha256) {
158	                    (Some(_), Some(_)) => {
159	                        anyhow::bail!(
160	                            "`--ws-token-file` and `--ws-token-sha256` are mutually exclusive"
161	                        );
162	                    }
163	                    (Some(token_file), None) => {
164	                        AppServerWebsocketCapabilityTokenSource::TokenFile {
165	                            token_file: absolute_path_arg("--ws-token-file", token_file)?,
166	                        }
167	                    }
168	                    (None, Some(token_sha256)) => {
169	                        AppServerWebsocketCapabilityTokenSource::TokenSha256 {
170	                            token_sha256: sha256_digest_arg("--ws-token-sha256", &token_sha256)?,
171	                        }
172	                    }
173	                    (None, None) => {
174	                        anyhow::bail!(
175	                            "`--ws-token-file` or `--ws-token-sha256` is required when `--ws-auth capability-token` is set"
176	                        );
177	                    }
178	                };
179	                Some(AppServerWebsocketAuthConfig::CapabilityToken { source })
180	            }
181	            Some(WebsocketAuthCliMode::SignedBearerToken) => {
182	                if self.ws_token_file.is_some() || self.ws_token_sha256.is_some() {
183	                    anyhow::bail!(
184	                        "`--ws-token-file` and `--ws-token-sha256` require `--ws-auth capability-token`, not `signed-bearer-token`"
185	                    );
186	                }
187	                let shared_secret_file = self.ws_shared_secret_file.context(
188	                    "`--ws-shared-secret-file` is required when `--ws-auth signed-bearer-token` is set",
189	                )?;
190	                Some(AppServerWebsocketAuthConfig::SignedBearerToken {
191	                    shared_secret_file: absolute_path_arg(
192	                        "--ws-shared-secret-file",
193	                        shared_secret_file,
194	                    )?,
195	                    issuer: normalize(self.ws_issuer),
196	                    audience: normalize(self.ws_audience),
197	                    max_clock_skew_seconds: self
198	                        .ws_max_clock_skew_seconds
199	                        .unwrap_or(DEFAULT_MAX_CLOCK_SKEW_SECONDS),
200	                })
201	            }
202	            None => {
203	                if self.ws_token_file.is_some()
204	                    || self.ws_token_sha256.is_some()
205	                    || self.ws_shared_secret_file.is_some()
206	                    || self.ws_issuer.is_some()
207	                    || self.ws_audience.is_some()
208	                    || self.ws_max_clock_skew_seconds.is_some()
209	                {
210	                    anyhow::bail!(
211	                        "websocket auth flags require `--ws-auth capability-token` or `--ws-auth signed-bearer-token`"
212	                    );
213	                }
214	                None
215	            }
216	        };
217	
218	        Ok(AppServerWebsocketAuthSettings { config })
219	    }
220	}
