222	pub fn policy_from_settings(
223	    settings: &AppServerWebsocketAuthSettings,
224	) -> io::Result<WebsocketAuthPolicy> {
225	    let mode = match settings.config.as_ref() {
226	        Some(AppServerWebsocketAuthConfig::CapabilityToken { source }) => match source {
227	            AppServerWebsocketCapabilityTokenSource::TokenFile { token_file } => {
228	                let token = read_trimmed_secret(token_file.as_ref())?;
229	                Some(WebsocketAuthMode::CapabilityToken {
230	                    token_sha256: sha256_digest(token.as_bytes()),
231	                })
232	            }
233	            AppServerWebsocketCapabilityTokenSource::TokenSha256 { token_sha256 } => {
234	                Some(WebsocketAuthMode::CapabilityToken {
235	                    token_sha256: *token_sha256,
236	                })
237	            }
238	        },
239	        Some(AppServerWebsocketAuthConfig::SignedBearerToken {
240	            shared_secret_file,
241	            issuer,
242	            audience,
243	            max_clock_skew_seconds,
244	        }) => {
245	            let shared_secret = read_trimmed_secret(shared_secret_file.as_ref())?.into_bytes();
246	            validate_signed_bearer_secret(shared_secret_file.as_ref(), &shared_secret)?;
247	            let max_clock_skew_seconds = i64::try_from(*max_clock_skew_seconds).map_err(|_| {
248	                io::Error::new(
249	                    ErrorKind::InvalidInput,
250	                    "websocket auth clock skew must fit in a signed 64-bit integer",
251	                )
252	            })?;
253	            Some(WebsocketAuthMode::SignedBearerToken {
254	                shared_secret,
255	                issuer: issuer.clone(),
256	                audience: audience.clone(),
257	                max_clock_skew_seconds,
258	            })
259	        }
260	        None => None,
261	    };
262	
263	    Ok(WebsocketAuthPolicy { mode })
264	}
