273	pub(crate) fn authorize_upgrade(
274	    headers: &HeaderMap,
275	    policy: &WebsocketAuthPolicy,
276	) -> Result<(), WebsocketAuthError> {
277	    let Some(mode) = policy.mode.as_ref() else {
278	        return Ok(());
279	    };
280	
281	    let token = bearer_token_from_headers(headers)?;
282	    match mode {
283	        WebsocketAuthMode::CapabilityToken { token_sha256 } => {
284	            let actual_sha256 = sha256_digest(token.as_bytes());
285	            if constant_time_eq_32(token_sha256, &actual_sha256) {
286	                Ok(())
287	            } else {
288	                Err(unauthorized("invalid websocket bearer token"))
289	            }
290	        }
291	        WebsocketAuthMode::SignedBearerToken {
292	            shared_secret,
293	            issuer,
294	            audience,
295	            max_clock_skew_seconds,
296	        } => verify_signed_bearer_token(
297	            token,
298	            shared_secret,
299	            issuer.as_deref(),
300	            audience.as_deref(),
301	            *max_clock_skew_seconds,
302	        ),
303	    }
304	}
305	
306	fn verify_signed_bearer_token(
307	    token: &str,
308	    shared_secret: &[u8],
309	    issuer: Option<&str>,
310	    audience: Option<&str>,
311	    max_clock_skew_seconds: i64,
312	) -> Result<(), WebsocketAuthError> {
313	    let claims = decode_jwt_claims(token, shared_secret)?;
314	    validate_jwt_claims(&claims, issuer, audience, max_clock_skew_seconds)
315	}
316	
317	fn decode_jwt_claims(token: &str, shared_secret: &[u8]) -> Result<JwtClaims, WebsocketAuthError> {
318	    let mut validation = Validation::new(Algorithm::HS256);
319	    validation.required_spec_claims.clear();
320	    validation.validate_exp = false;
321	    validation.validate_nbf = false;
322	    validation.validate_aud = false;
323	
324	    decode::<JwtClaims>(token, &DecodingKey::from_secret(shared_secret), &validation)
325	        .map(|token_data| token_data.claims)
326	        .map_err(|_| unauthorized("invalid websocket jwt"))
327	}
328	
329	fn validate_jwt_claims(
330	    claims: &JwtClaims,
331	    issuer: Option<&str>,
332	    audience: Option<&str>,
333	    max_clock_skew_seconds: i64,
334	) -> Result<(), WebsocketAuthError> {
335	    let now = OffsetDateTime::now_utc().unix_timestamp();
336	    if now > claims.exp.saturating_add(max_clock_skew_seconds) {
337	        return Err(unauthorized("expired websocket jwt"));
338	    }
339	    if let Some(nbf) = claims.nbf
340	        && now < nbf.saturating_sub(max_clock_skew_seconds)
341	    {
342	        return Err(unauthorized("websocket jwt is not valid yet"));
343	    }
344	    if let Some(expected_issuer) = issuer
345	        && claims.iss.as_deref() != Some(expected_issuer)
346	    {
347	        return Err(unauthorized("websocket jwt issuer mismatch"));
348	    }
349	    if let Some(expected_audience) = audience
350	        && !audience_matches(claims.aud.as_ref(), expected_audience)
351	    {
352	        return Err(unauthorized("websocket jwt audience mismatch"));
353	    }
354	
355	    Ok(())
356	}
357	
358	fn audience_matches(audience: Option<&JwtAudienceClaim>, expected_audience: &str) -> bool {
359	    match audience {
360	        Some(JwtAudienceClaim::Single(actual)) => actual == expected_audience,
361	        Some(JwtAudienceClaim::Multiple(actual)) => {
362	            actual.iter().any(|audience| audience == expected_audience)
363	        }
364	        None => false,
365	    }
366	}
367	
368	fn bearer_token_from_headers(headers: &HeaderMap) -> Result<&str, WebsocketAuthError> {
369	    let raw_header = headers
370	        .get(AUTHORIZATION)
371	        .ok_or_else(|| unauthorized("missing websocket bearer token"))?;
372	    let header = raw_header
373	        .to_str()
374	        .map_err(|_| unauthorized(INVALID_AUTHORIZATION_HEADER_MESSAGE))?;
375	    let Some((scheme, token)) = header.split_once(' ') else {
376	        return Err(unauthorized(INVALID_AUTHORIZATION_HEADER_MESSAGE));
377	    };
378	    if !scheme.eq_ignore_ascii_case("Bearer") {
379	        return Err(unauthorized(INVALID_AUTHORIZATION_HEADER_MESSAGE));
380	    }
381	    let token = token.trim();
382	    if token.is_empty() {
383	        return Err(unauthorized(INVALID_AUTHORIZATION_HEADER_MESSAGE));
384	    }
385	    Ok(token)
386	}
387	
388	fn validate_signed_bearer_secret(path: &Path, shared_secret: &[u8]) -> io::Result<()> {
389	    if shared_secret.len() < MIN_SIGNED_BEARER_SECRET_BYTES {
390	        return Err(io::Error::new(
391	            ErrorKind::InvalidInput,
392	            format!(
393	                "signed websocket bearer secret {} must be at least {MIN_SIGNED_BEARER_SECRET_BYTES} bytes",
394	                path.display()
395	            ),
396	        ));
397	    }
398	    Ok(())
399	}
