401	fn read_trimmed_secret(path: &std::path::Path) -> io::Result<String> {
402	    let raw = std::fs::read_to_string(path).map_err(|err| {
403	        io::Error::new(
404	            err.kind(),
405	            format!(
406	                "failed to read websocket auth secret {}: {err}",
407	                path.display()
408	            ),
409	        )
410	    })?;
411	    let trimmed = raw.trim();
412	    if trimmed.is_empty() {
413	        return Err(io::Error::new(
414	            ErrorKind::InvalidInput,
415	            format!("websocket auth secret {} must not be empty", path.display()),
416	        ));
417	    }
418	    Ok(trimmed.to_string())
419	}
