421	fn absolute_path_arg(flag_name: &str, path: PathBuf) -> anyhow::Result<AbsolutePathBuf> {
422	    AbsolutePathBuf::try_from(path).with_context(|| format!("{flag_name} must be an absolute path"))
423	}
