425	fn sha256_digest_arg(flag_name: &str, value: &str) -> anyhow::Result<[u8; 32]> {
426	    let trimmed = value.trim();
427	    if trimmed.len() != 64 {
428	        anyhow::bail!("{flag_name} must be a 64-character hex SHA-256 digest");
429	    }
430	
431	    let mut digest = [0u8; 32];
432	    for (index, pair) in trimmed.as_bytes().chunks_exact(2).enumerate() {
433	        let high = hex_nibble(flag_name, pair[0])?;
434	        let low = hex_nibble(flag_name, pair[1])?;
435	        digest[index] = (high << 4) | low;
436	    }
437	    Ok(digest)
438	}
439	
440	fn hex_nibble(flag_name: &str, byte: u8) -> anyhow::Result<u8> {
441	    match byte {
442	        b'0'..=b'9' => Ok(byte - b'0'),
443	        b'a'..=b'f' => Ok(byte - b'a' + 10),
444	        b'A'..=b'F' => Ok(byte - b'A' + 10),
445	        _ => anyhow::bail!("{flag_name} must be a 64-character hex SHA-256 digest"),
446	    }
447	}
448	
449	fn sha256_digest(input: &[u8]) -> [u8; 32] {
450	    let mut digest = [0u8; 32];
451	    digest.copy_from_slice(&Sha256::digest(input));
452	    digest
453	}
