71	impl RemoteControlHandle {
72	    pub fn enable(
73	        &self,
74	    ) -> Result<RemoteControlStatusChangedNotification, RemoteControlUnavailable> {
75	        if !self.state_db_available {
76	            warn!("remote control cannot be enabled because sqlite state db is unavailable");
77	            return Err(RemoteControlUnavailable);
78	        }
79	
80	        let enabled_changed = self.enabled_tx.send_if_modified(|state| {
81	            let changed = !*state;
82	            *state = true;
83	            changed
84	        });
85	
86	        let status = self.status();
87	        info!(
88	            enabled_changed,
89	            current_status = ?status.status,
90	            environment_id = ?status.environment_id,
91	            installation_id = %status.installation_id,
92	            server_name = %status.server_name,
93	            "remote control enable requested"
94	        );
95	        if matches!(
96	            status.status,
97	            RemoteControlConnectionStatus::Connected | RemoteControlConnectionStatus::Connecting
98	        ) {
99	            return Ok(status);
100	        }
101	
102	        Ok(self.publish_status(RemoteControlConnectionStatus::Connecting))
103	    }
104	
105	    pub fn disable(&self) -> RemoteControlStatusChangedNotification {
106	        let enabled_changed = self.enabled_tx.send_if_modified(|state| {
107	            let changed = *state;
108	            *state = false;
109	            changed
110	        });
111	
112	        let status = self.status();
113	        info!(
114	            enabled_changed,
115	            current_status = ?status.status,
116	            environment_id = ?status.environment_id,
117	            installation_id = %status.installation_id,
118	            server_name = %status.server_name,
119	            "remote control disable requested"
120	        );
121	        self.publish_status(RemoteControlConnectionStatus::Disabled)
122	    }
123	
124	    pub fn status(&self) -> RemoteControlStatusChangedNotification {
125	        self.status_tx.borrow().clone()
126	    }
127	
128	    pub fn status_receiver(&self) -> watch::Receiver<RemoteControlStatusChangedNotification> {
129	        self.status_tx.subscribe()
130	    }
131	
132	    fn publish_status(
133	        &self,
134	        connection_status: RemoteControlConnectionStatus,
135	    ) -> RemoteControlStatusChangedNotification {
136	        let mut status_change = None;
137	        self.status_tx.send_if_modified(|status| {
138	            let next_status =
139	                remote_control_status_with_connection_status(status, connection_status);
140	            if *status == next_status {
141	                return false;
142	            }
143	
144	            status_change = Some((status.clone(), next_status.clone()));
145	            *status = next_status;
146	            true
147	        });
148	        if let Some((previous_status, next_status)) = status_change {
149	            info!(
150	                previous_status = ?previous_status.status,
151	                next_status = ?next_status.status,
152	                previous_environment_id = ?previous_status.environment_id,
153	                next_environment_id = ?next_status.environment_id,
154	                installation_id = %next_status.installation_id,
155	                server_name = %next_status.server_name,
156	                "remote control handle status changed"
157	            );
158	        }
159	        self.status()
160	    }
161	}
