168	        status: connection_status,
169	        server_name: status.server_name.clone(),
170	        installation_id: status.installation_id.clone(),
171	        environment_id: if connection_status == RemoteControlConnectionStatus::Disabled {
172	            None
173	        } else {
174	            status.environment_id.clone()
175	        },
176	    }
177	}
