179	pub async fn start_remote_control(
180	    config: RemoteControlStartConfig,
181	    state_db: Option<Arc<StateRuntime>>,
182	    auth_manager: Arc<AuthManager>,
183	    transport_event_tx: mpsc::Sender<TransportEvent>,
184	    shutdown_token: CancellationToken,
185	    app_server_client_name_rx: Option<oneshot::Receiver<String>>,
186	    initial_enabled: bool,
187	) -> io::Result<(JoinHandle<()>, RemoteControlHandle)> {
188	    let state_db_available = state_db.is_some();
189	    let requested_initial_enabled = initial_enabled;
190	    let initial_enabled = initial_enabled && state_db_available;
191	    if requested_initial_enabled && !state_db_available {
192	        warn!("remote control disabled because sqlite state db is unavailable");
193	    }
194	    let remote_control_target = if initial_enabled {
195	        Some(normalize_remote_control_url(&config.remote_control_url)?)
196	    } else {
197	        None
198	    };
199	
200	    let (enabled_tx, enabled_rx) = watch::channel(initial_enabled);
201	    let server_name = gethostname().to_string_lossy().trim().to_string();
202	    let remote_control_url = config.remote_control_url;
203	    let installation_id = config.installation_id;
204	    let initial_status = RemoteControlStatusChangedNotification {
205	        status: if initial_enabled {
206	            RemoteControlConnectionStatus::Connecting
207	        } else {
208	            RemoteControlConnectionStatus::Disabled
209	        },
210	        server_name: server_name.clone(),
211	        installation_id: installation_id.clone(),
212	        environment_id: None,
213	    };
214	    let (status_tx, _status_rx) = watch::channel(initial_status);
215	    let status_publisher = RemoteControlStatusPublisher::new(status_tx.clone());
216	    info!(
217	        remote_control_url = %remote_control_url,
218	        installation_id = %installation_id,
219	        server_name = %server_name,
220	        state_db_available,
221	        initial_enabled,
222	        "starting app-server remote control websocket task"
223	    );
224	    let remote_control_url_for_log = remote_control_url.clone();
225	    let installation_id_for_log = installation_id.clone();
226	    let server_name_for_log = server_name.clone();
227	    let shutdown_token_for_log = shutdown_token.clone();
228	    let join_handle = tokio::spawn(async move {
229	        info!(
230	            remote_control_url = %remote_control_url_for_log,
231	            installation_id = %installation_id_for_log,
232	            server_name = %server_name_for_log,
233	            initial_enabled,
234	            "app-server remote control websocket task started"
235	        );
236	        let websocket_task = RemoteControlWebsocket::new(
237	            websocket::RemoteControlWebsocketConfig {
238	                remote_control_url,
239	                installation_id,
240	                remote_control_target,
241	                server_name,
242	            },
243	            state_db,
244	            auth_manager,
245	            RemoteControlChannels {
246	                transport_event_tx,
247	                status_publisher,
248	            },
249	            shutdown_token,
250	            enabled_rx,
251	        )
252	        .run(app_server_client_name_rx);
253	        match AssertUnwindSafe(websocket_task).catch_unwind().await {
254	            Ok(()) => {
255	                let shutdown_requested = shutdown_token_for_log.is_cancelled();
256	                if shutdown_requested {
257	                    info!(
258	                        remote_control_url = %remote_control_url_for_log,
259	                        installation_id = %installation_id_for_log,
260	                        server_name = %server_name_for_log,
261	                        shutdown_requested,
262	                        "app-server remote control websocket task exited"
263	                    );
264	                } else {
265	                    warn!(
266	                        remote_control_url = %remote_control_url_for_log,
267	                        installation_id = %installation_id_for_log,
268	                        server_name = %server_name_for_log,
269	                        shutdown_requested,
270	                        "app-server remote control websocket task exited without shutdown"
271	                    );
272	                }
273	            }
274	            Err(panic) => {
275	                error!(
276	                    remote_control_url = %remote_control_url_for_log,
277	                    installation_id = %installation_id_for_log,
278	                    server_name = %server_name_for_log,
279	                    "app-server remote control websocket task panicked"
280	                );
281	                std::panic::resume_unwind(panic);
282	            }
283	        }
284	    });
285	
286	    Ok((
287	        join_handle,
288	        RemoteControlHandle {
289	            enabled_tx: Arc::new(enabled_tx),
290	            status_tx: Arc::new(status_tx),
291	            state_db_available,
292	        },
293	    ))
294	}
