259	impl Daemon {
260	    fn from_environment() -> Result<Self> {
261	        let codex_home = find_codex_home().context("failed to resolve CODEX_HOME")?;
262	        let socket_path = app_server_control_socket_path(codex_home.as_path())?
263	            .as_path()
264	            .to_path_buf();
265	        let state_dir = codex_home.as_path().join(STATE_DIR_NAME);
266	        Ok(Self {
267	            socket_path,
268	            pid_file: state_dir.join(PID_FILE_NAME),
269	            update_pid_file: state_dir.join(UPDATE_PID_FILE_NAME),
270	            operation_lock_file: state_dir.join(OPERATION_LOCK_FILE_NAME),
271	            settings_file: state_dir.join(SETTINGS_FILE_NAME),
272	            managed_codex_bin: managed_codex_bin(codex_home.as_path()),
273	        })
274	    }
