276	    async fn run(&self, command: LifecycleCommand) -> Result<LifecycleOutput> {
277	        match command {
278	            LifecycleCommand::Start => {
279	                let _operation_lock = self.acquire_operation_lock().await?;
280	                self.start().await
281	            }
282	            LifecycleCommand::Restart => {
283	                let _operation_lock = self.acquire_operation_lock().await?;
284	                self.restart().await
285	            }
286	            LifecycleCommand::Stop => {
287	                let _operation_lock = self.acquire_operation_lock().await?;
288	                self.stop().await
289	            }
290	            LifecycleCommand::Version => self.version().await,
291	        }
292	    }
293	
294	    async fn start(&self) -> Result<LifecycleOutput> {
295	        let settings = self.load_settings().await?;
296	        if let Ok(info) = client::probe(&self.socket_path).await {
297	            return Ok(self
298	                .output(
299	                    LifecycleStatus::AlreadyRunning,
300	                    self.running_backend(&settings).await?,
301	                    /*pid*/ None,
302	                    Some(info.app_server_version),
303	                )
304	                .await);
305	        }
306	
307	        if self.running_backend_instance(&settings).await?.is_some() {
308	            let info = self.wait_until_ready().await?;
309	            return Ok(self
310	                .output(
311	                    LifecycleStatus::AlreadyRunning,
312	                    Some(BackendKind::Pid),
313	                    /*pid*/ None,
314	                    Some(info.app_server_version),
315	                )
316	                .await);
317	        }
318	
319	        self.ensure_managed_codex_bin()?;
320	        let pid = self.start_managed_backend(&settings).await?;
321	        let info = self.wait_until_ready().await?;
322	        Ok(self
323	            .output(
324	                LifecycleStatus::Started,
325	                Some(BackendKind::Pid),
326	                pid,
327	                Some(info.app_server_version),
328	            )
329	            .await)
330	    }
331	
332	    async fn restart(&self) -> Result<LifecycleOutput> {
333	        let settings = self.load_settings().await?;
334	        if client::probe(&self.socket_path).await.is_ok()
335	            && self.running_backend(&settings).await?.is_none()
336	        {
337	            return Err(anyhow!(
338	                "app server is running but is not managed by codex app-server daemon"
339	            ));
340	        }
341	
342	        self.ensure_managed_codex_bin()?;
343	        if let Some(backend) = self.running_backend_instance(&settings).await? {
344	            backend.stop().await?;
345	        }
346	
347	        let pid = self.start_managed_backend(&settings).await?;
348	        let info = self.wait_until_ready().await?;
349	        Ok(self
350	            .output(
351	                LifecycleStatus::Restarted,
352	                Some(BackendKind::Pid),
353	                pid,
354	                Some(info.app_server_version),
355	            )
356	            .await)
357	    }
