359	    #[cfg(unix)]
360	    pub(crate) async fn try_restart_if_running(
361	        &self,
362	        mode: RestartMode,
363	        updater_refresh_mode: UpdaterRefreshMode,
364	        managed_codex_bin: &Path,
365	    ) -> Result<RestartIfRunningOutcome> {
366	        let operation_lock = self.open_operation_lock_file().await?;
367	        if !try_lock_file(&operation_lock)? {
368	            return Ok(RestartIfRunningOutcome::Busy);
369	        }
370	        let settings = self.load_settings().await?;
371	        let outcome = if let Some(backend) = self.running_backend_instance(&settings).await? {
372	            let info = client::probe(&self.socket_path).await.ok();
373	            let managed_version = if info.is_some() {
374	                Some(managed_codex_version(managed_codex_bin).await?)
375	            } else {
376	                None
377	            };
378	            match restart_decision(mode, info.as_ref(), managed_version.as_deref()) {
379	                RestartDecision::NotReady => return Ok(RestartIfRunningOutcome::NotReady),
380	                RestartDecision::AlreadyCurrent => RestartIfRunningOutcome::AlreadyCurrent,
381	                RestartDecision::Restart => {
382	                    backend.stop().await?;
383	                    let _ = self
384	                        .start_managed_backend_with_bin(&settings, managed_codex_bin)
385	                        .await?;
386	                    self.wait_until_ready().await?;
387	                    RestartIfRunningOutcome::Restarted
388	                }
389	            }
390	        } else if client::probe(&self.socket_path).await.is_ok() {
391	            return Err(anyhow!(
392	                "app server is running but is not managed by codex app-server daemon"
393	            ));
394	        } else {
395	            RestartIfRunningOutcome::NotRunning
396	        };
397	
398	        if should_reexec_updater(updater_refresh_mode, outcome) {
399	            crate::update_loop::reexec_managed_updater(managed_codex_bin)?;
400	        }
401	
402	        Ok(outcome)
403	    }
