448	    async fn wait_until_ready(&self) -> Result<client::ProbeInfo> {
449	        let deadline = tokio::time::Instant::now() + START_TIMEOUT;
450	        loop {
451	            match client::probe(&self.socket_path).await {
452	                Ok(info) => return Ok(info),
453	                Err(err) if tokio::time::Instant::now() < deadline => {
454	                    let _ = err;
455	                    sleep(START_POLL_INTERVAL).await;
456	                }
457	                Err(err) => {
458	                    let context = self.app_server_not_ready_context().await;
459	                    return Err(err).context(context);
460	                }
461	            }
462	        }
463	    }
