465	    async fn app_server_not_ready_context(&self) -> String {
466	        let mut context = format!(
467	            "app server did not become ready on {}",
468	            self.socket_path.display()
469	        );
470	        self.append_daemon_app_server_context(&mut context).await;
471	        backend::append_stderr_log_tail_context(&self.pid_file, &mut context).await;
472	        context
473	    }
