479	            .unwrap_or_else(|| "unknown".to_string());
480	        context.push_str(&format!(
481	            "\n\nDaemon used app-server:\n  path: {}\n  version: {managed_codex_version}",
482	            self.managed_codex_bin.display()
483	        ));
484	    }
