523	    }
524	
525	    async fn set_remote_control_locked(
526	        &self,
527	        mode: RemoteControlMode,
528	    ) -> Result<RemoteControlOutput> {
529	        let previous_settings = self.load_settings().await?;
530	        let mut settings = previous_settings.clone();
531	        let remote_control_enabled = mode.is_enabled();
532	        let backend = self.running_backend_instance(&previous_settings).await?;
533	
534	        if backend.is_none() && client::probe(&self.socket_path).await.is_ok() {
535	            return Err(anyhow!(
536	                "app server is running but is not managed by codex app-server daemon"
537	            ));
538	        }
539	
540	        if settings.remote_control_enabled == remote_control_enabled {
541	            let info = if backend.is_some() {
542	                Some(self.wait_until_ready().await?)
543	            } else {
544	                None
545	            };
546	            return Ok(self.remote_control_output(
547	                already_remote_control_status(mode),
548	                backend.map(|_| BackendKind::Pid),
549	                remote_control_enabled,
550	                info.map(|info| info.app_server_version),
551	            ));
552	        }
553	
554	        settings.remote_control_enabled = remote_control_enabled;
555	        settings.save(&self.settings_file).await?;
556	
557	        let app_server_version = if let Some(backend) = backend {
558	            self.ensure_managed_codex_bin()?;
559	            backend.stop().await?;
560	            let _ = self.start_managed_backend(&settings).await?;
561	            Some(self.wait_until_ready().await?.app_server_version)
562	        } else {
563	            None
564	        };
565	
566	        Ok(self.remote_control_output(
567	            remote_control_status(mode),
568	            app_server_version.as_ref().map(|_| BackendKind::Pid),
569	            remote_control_enabled,
570	            app_server_version,
571	        ))
572	    }
573	
574	    async fn bootstrap_locked(&self, options: BootstrapOptions) -> Result<BootstrapOutput> {
575	        self.ensure_managed_codex_bin()?;
576	
577	        let settings = DaemonSettings {
578	            remote_control_enabled: options.remote_control_enabled,
579	        };
580	        if client::probe(&self.socket_path).await.is_ok()
581	            && self.running_backend(&settings).await?.is_none()
582	        {
583	            return Err(anyhow!(
584	                "app server is running but is not managed by codex app-server daemon"
585	            ));
586	        }
587	        settings.save(&self.settings_file).await?;
588	
589	        if let Some(backend) = self.running_backend_instance(&settings).await? {
590	            backend.stop().await?;
591	        }
592	
593	        let backend = backend::pid_backend(self.backend_paths(&settings));
594	        backend.start().await?;
595	        let updater = backend::pid_update_loop_backend(self.backend_paths(&settings));
596	        if updater.is_starting_or_running().await? {
597	            updater.stop().await?;
598	        }
599	        updater.start().await?;
600	
601	        let info = self.wait_until_ready().await?;
602	        let managed_codex_version = self.managed_codex_version_best_effort().await;
603	        Ok(BootstrapOutput {
604	            status: BootstrapStatus::Bootstrapped,
605	            backend: BackendKind::Pid,
606	            auto_update_enabled: true,
607	            remote_control_enabled: settings.remote_control_enabled,
608	            managed_codex_path: self.managed_codex_bin.clone(),
609	            managed_codex_version,
610	            socket_path: self.socket_path.clone(),
611	            cli_version: env!("CARGO_PKG_VERSION").to_string(),
612	            app_server_version: info.app_server_version,
613	        })
614	    }
