700	    async fn acquire_operation_lock(&self) -> Result<tokio::fs::File> {
701	        let operation_lock = self.open_operation_lock_file().await?;
702	        let deadline = tokio::time::Instant::now() + OPERATION_LOCK_TIMEOUT;
703	        while !try_lock_file(&operation_lock)? {
704	            if tokio::time::Instant::now() >= deadline {
705	                return Err(anyhow!(
706	                    "timed out waiting for daemon operation lock {}",
707	                    self.operation_lock_file.display()
708	                ));
709	            }
710	            sleep(START_POLL_INTERVAL).await;
711	        }
712	        Ok(operation_lock)
713	    }
714	
715	    async fn open_operation_lock_file(&self) -> Result<tokio::fs::File> {
716	        if let Some(parent) = self.operation_lock_file.parent() {
717	            tokio::fs::create_dir_all(parent).await.with_context(|| {
718	                format!(
719	                    "failed to create daemon state directory {}",
720	                    parent.display()
721	                )
722	            })?;
723	        }
724	        tokio::fs::OpenOptions::new()
725	            .create(true)
726	            .truncate(false)
727	            .write(true)
728	            .open(&self.operation_lock_file)
729	            .await
730	            .with_context(|| {
731	                format!(
732	                    "failed to open daemon operation lock {}",
733	                    self.operation_lock_file.display()
734	                )
735	            })
736	    }
