791	fn restart_decision(
792	    mode: RestartMode,
793	    info: Option<&client::ProbeInfo>,
794	    managed_version: Option<&str>,
795	) -> RestartDecision {
796	    match (mode, info, managed_version) {
797	        (RestartMode::IfVersionChanged, None, _) => RestartDecision::NotReady,
798	        (RestartMode::IfVersionChanged, Some(info), Some(managed_version))
799	            if info.app_server_version == managed_version =>
800	        {
801	            RestartDecision::AlreadyCurrent
802	        }
803	        _ => RestartDecision::Restart,
804	    }
