816	#[cfg(unix)]
817	fn try_lock_file(file: &tokio::fs::File) -> Result<bool> {
818	    use std::os::fd::AsRawFd;
819	
820	    let result = unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) };
821	    if result == 0 {
822	        return Ok(true);
823	    }
824	
825	    let err = std::io::Error::last_os_error();
826	    if err.raw_os_error() == Some(libc::EWOULDBLOCK) {
827	        return Ok(false);
828	    }
829	    Err(err).context("failed to lock daemon operation")
830	}
