6	pub(crate) fn compute_source_filters(
7	    source_kinds: Option<Vec<ThreadSourceKind>>,
8	) -> (Vec<CoreSessionSource>, Option<Vec<ThreadSourceKind>>) {
9	    let Some(source_kinds) = source_kinds else {
10	        return (INTERACTIVE_SESSION_SOURCES.to_vec(), None);
11	    };
12	
13	    if source_kinds.is_empty() {
14	        return (INTERACTIVE_SESSION_SOURCES.to_vec(), None);
15	    }
16	
17	    let requires_post_filter = source_kinds.iter().any(|kind| {
18	        matches!(
19	            kind,
20	            ThreadSourceKind::Exec
21	                | ThreadSourceKind::AppServer
22	                | ThreadSourceKind::SubAgent
23	                | ThreadSourceKind::SubAgentReview
24	                | ThreadSourceKind::SubAgentCompact
25	                | ThreadSourceKind::SubAgentThreadSpawn
26	                | ThreadSourceKind::SubAgentOther
27	                | ThreadSourceKind::Unknown
28	        )
29	    });
30	
31	    if requires_post_filter {
32	        (Vec::new(), Some(source_kinds))
33	    } else {
34	        let interactive_sources = source_kinds
35	            .iter()
36	            .filter_map(|kind| match kind {
37	                ThreadSourceKind::Cli => Some(CoreSessionSource::Cli),
38	                ThreadSourceKind::VsCode => Some(CoreSessionSource::VSCode),
39	                ThreadSourceKind::Exec
40	                | ThreadSourceKind::AppServer
41	                | ThreadSourceKind::SubAgent
42	                | ThreadSourceKind::SubAgentReview
43	                | ThreadSourceKind::SubAgentCompact
44	                | ThreadSourceKind::SubAgentThreadSpawn
45	                | ThreadSourceKind::SubAgentOther
46	                | ThreadSourceKind::Unknown => None,
47	            })
48	            .collect::<Vec<_>>();
49	        (interactive_sources, Some(source_kinds))
50	    }
51	}
52	
53	pub(crate) fn source_kind_matches(source: &CoreSessionSource, filter: &[ThreadSourceKind]) -> bool {
54	    filter.iter().any(|kind| match kind {
55	        ThreadSourceKind::Cli => matches!(source, CoreSessionSource::Cli),
56	        ThreadSourceKind::VsCode => matches!(source, CoreSessionSource::VSCode),
57	        ThreadSourceKind::Exec => matches!(source, CoreSessionSource::Exec),
58	        ThreadSourceKind::AppServer => matches!(source, CoreSessionSource::Mcp),
59	        ThreadSourceKind::SubAgent => matches!(source, CoreSessionSource::SubAgent(_)),
60	        ThreadSourceKind::SubAgentReview => {
61	            matches!(
62	                source,
63	                CoreSessionSource::SubAgent(CoreSubAgentSource::Review)
64	            )
65	        }
66	        ThreadSourceKind::SubAgentCompact => {
67	            matches!(
68	                source,
69	                CoreSessionSource::SubAgent(CoreSubAgentSource::Compact)
70	            )
71	        }
72	        ThreadSourceKind::SubAgentThreadSpawn => matches!(
73	            source,
74	            CoreSessionSource::SubAgent(CoreSubAgentSource::ThreadSpawn { .. })
75	        ),
76	        ThreadSourceKind::SubAgentOther => matches!(
77	            source,
78	            CoreSessionSource::SubAgent(CoreSubAgentSource::Other(_))
79	        ),
80	        ThreadSourceKind::Unknown => matches!(source, CoreSessionSource::Unknown),
81	    })
82	}
