285	pub(crate) fn resolve_thread_status(
286	    status: ThreadStatus,
287	    has_in_progress_turn: bool,
288	) -> ThreadStatus {
289	    // Running-turn events can arrive before the watch runtime state is observed by
290	    // the listener loop. In that window we prefer to reflect a real active turn as
291	    // `Active` instead of `Idle`/`NotLoaded`.
292	    if has_in_progress_turn && matches!(status, ThreadStatus::Idle | ThreadStatus::NotLoaded) {
293	        return ThreadStatus::Active {
294	            active_flags: Vec::new(),
295	        };
296	    }
297	
298	    status
299	}
