81	impl std::fmt::Display for AppServerTransportParseError {
82	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
83	        match self {
84	            AppServerTransportParseError::UnsupportedListenUrl(listen_url) => write!(
85	                f,
86	                "unsupported --listen URL `{listen_url}`; expected `stdio://`, `unix://`, `unix://PATH`, `ws://IP:PORT`, or `off`"
87	            ),
88	            AppServerTransportParseError::InvalidUnixSocketPath {
89	                listen_url,
90	                message,
91	            } => write!(
92	                f,
93	                "invalid unix socket --listen URL `{listen_url}`; failed to resolve socket path: {message}"
94	            ),
95	            AppServerTransportParseError::InvalidWebSocketListenUrl(listen_url) => write!(
96	                f,
97	                "invalid websocket --listen URL `{listen_url}`; expected `ws://IP:PORT`"
98	            ),
99	        }
100	    }
