106	    pub const DEFAULT_LISTEN_URL: &'static str = "stdio://";
107	
108	    pub fn from_listen_url(listen_url: &str) -> Result<Self, AppServerTransportParseError> {
109	        if listen_url == Self::DEFAULT_LISTEN_URL {
110	            return Ok(Self::Stdio);
111	        }
112	
113	        if let Some(raw_socket_path) = listen_url.strip_prefix("unix://") {
114	            let socket_path = if raw_socket_path.is_empty() {
115	                let codex_home = find_codex_home().map_err(|err| {
116	                    AppServerTransportParseError::InvalidUnixSocketPath {
117	                        listen_url: listen_url.to_string(),
118	                        message: format!("failed to resolve CODEX_HOME: {err}"),
119	                    }
