2002	    async fn thread_loaded_list_response_inner(
2003	        &self,
2004	        params: ThreadLoadedListParams,
2005	    ) -> Result<ThreadLoadedListResponse, JSONRPCErrorError> {
2006	        let ThreadLoadedListParams { cursor, limit } = params;
2007	        let mut data: Vec<String> = self
2008	            .thread_manager
2009	            .list_thread_ids()
2010	            .await
2011	            .into_iter()
2012	            .map(|thread_id| thread_id.to_string())
2013	            .collect();
2014	
2015	        if data.is_empty() {
2016	            return Ok(ThreadLoadedListResponse {
2017	                data,
2018	                next_cursor: None,
2019	            });
2020	        }
2021	
2022	        data.sort();
2023	        let total = data.len();
2024	        let start = match cursor {
2025	            Some(cursor) => {
2026	                let cursor = match ThreadId::from_string(&cursor) {
2027	                    Ok(id) => id.to_string(),
2028	                    Err(_) => return Err(invalid_request(format!("invalid cursor: {cursor}"))),
2029	                };
2030	                match data.binary_search(&cursor) {
2031	                    Ok(idx) => idx + 1,
2032	                    Err(idx) => idx,
2033	                }
2034	            }
2035	            None => 0,
2036	        };
2037	
2038	        let effective_limit = limit.unwrap_or(total as u32).max(1) as usize;
2039	        let end = start.saturating_add(effective_limit).min(total);
2040	        let page = data[start..end].to_vec();
2041	        let next_cursor = page.last().filter(|_| end < total).cloned();
2042	
2043	        Ok(ThreadLoadedListResponse {
2044	            data: page,
2045	            next_cursor,
2046	        })
2047	    }
