2068	    /// Builds the API view for `thread/read` from persisted metadata plus optional live state.
2069	    async fn read_thread_view(
2070	        &self,
2071	        thread_id: ThreadId,
2072	        include_turns: bool,
2073	    ) -> Result<Thread, ThreadReadViewError> {
2074	        let loaded_thread = self.thread_manager.get_thread(thread_id).await.ok();
2075	        let mut thread = if include_turns {
2076	            if let Some(loaded_thread) = loaded_thread.as_ref() {
2077	                // Loaded thread with turns: use persisted metadata when it exists,
2078	                // but reconstruct turns from the live ThreadStore history.
2079	                let persisted_thread = self
2080	                    .load_persisted_thread_for_read(thread_id, /*include_turns*/ false)
2081	                    .await?;
2082	                self.load_live_thread_view(
2083	                    thread_id,
2084	                    include_turns,
2085	                    loaded_thread,
2086	                    persisted_thread,
2087	                )
2088	                .await?
2089	            } else if let Some(thread) = self
2090	                .load_persisted_thread_for_read(thread_id, include_turns)
2091	                .await?
2092	            {
2093	                // Unloaded thread with turns: load metadata and history together
2094	                // from the ThreadStore.
2095	                thread
2096	            } else {
2097	                return Err(ThreadReadViewError::InvalidRequest(format!(
2098	                    "thread not loaded: {thread_id}"
2099	                )));
2100	            }
2101	        } else if let Some(thread) = self
2102	            .load_persisted_thread_for_read(thread_id, include_turns)
2103	            .await?
2104	        {
2105	            // Persisted metadata-only read: no live thread state is needed.
2106	            thread
2107	        } else if let Some(loaded_thread) = loaded_thread.as_ref() {
2108	            // Loaded metadata-only read before persistence is materialized: build
2109	            // the response from the live thread snapshot.
2110	            self.load_live_thread_view(
2111	                thread_id,
2112	                include_turns,
2113	                loaded_thread,
2114	                /*persisted_thread*/ None,
2115	            )
2116	            .await?
2117	        } else {
2118	            return Err(ThreadReadViewError::InvalidRequest(format!(
2119	                "thread not loaded: {thread_id}"
2120	            )));
2121	        };
2122	
2123	        let has_live_in_progress_turn = if let Some(loaded_thread) = loaded_thread.as_ref() {
2124	            matches!(loaded_thread.agent_status().await, AgentStatus::Running)
2125	        } else {
2126	            false
2127	        };
2128	
2129	        let thread_status = self
2130	            .thread_watch_manager
2131	            .loaded_status_for_thread(&thread.id)
2132	            .await;
2133	
2134	        set_thread_status_and_interrupt_stale_turns(
2135	            &mut thread,
2136	            thread_status,
2137	            has_live_in_progress_turn,
2138	        );
2139	        Ok(thread)
2140	    }
