2142	    async fn load_persisted_thread_for_read(
2143	        &self,
2144	        thread_id: ThreadId,
2145	        include_turns: bool,
2146	    ) -> Result<Option<Thread>, ThreadReadViewError> {
2147	        let fallback_provider = self.config.model_provider_id.as_str();
2148	        match self
2149	            .thread_store
2150	            .read_thread(StoreReadThreadParams {
2151	                thread_id,
2152	                include_archived: true,
2153	                include_history: include_turns,
2154	            })
2155	            .await
2156	        {
