2171	                thread_id: missing_thread_id,
2172	            }) if missing_thread_id == thread_id => Ok(None),
2173	            Err(ThreadStoreError::InvalidRequest { message }) => {
2174	                Err(ThreadReadViewError::InvalidRequest(message))
