2182	    /// Builds a `thread/read` view from a loaded thread plus optional persisted metadata.
2183	    async fn load_live_thread_view(
2184	        &self,
2185	        thread_id: ThreadId,
2186	        include_turns: bool,
2187	        loaded_thread: &CodexThread,
2188	        persisted_thread: Option<Thread>,
2189	    ) -> Result<Thread, ThreadReadViewError> {
2190	        let config_snapshot = loaded_thread.config_snapshot().await;
2191	        if include_turns && config_snapshot.ephemeral {
2192	            return Err(ThreadReadViewError::InvalidRequest(
2193	                "ephemeral threads do not support includeTurns".to_string(),
2194	            ));
2195	        }
2196	        let fallback_thread =
2197	            build_thread_from_loaded_snapshot(thread_id, &config_snapshot, loaded_thread);
2198	        let mut thread = if let Some(mut thread) = persisted_thread {
2199	            if thread.path.is_none() {
2200	                thread.path = fallback_thread.path.clone();
2201	            }
2202	            thread.session_id.clone_from(&fallback_thread.session_id);
2203	            thread.ephemeral = fallback_thread.ephemeral;
2204	            thread
2205	        } else {
2206	            fallback_thread
2207	        };
2208	        self.apply_thread_read_store_fields(thread_id, &mut thread, include_turns, loaded_thread)
2209	            .await?;
