2233	    async fn thread_turns_list_response_inner(
2234	        &self,
2235	        params: ThreadTurnsListParams,
2236	    ) -> Result<ThreadTurnsListResponse, JSONRPCErrorError> {
2237	        let ThreadTurnsListParams {
2238	            thread_id,
2239	            cursor,
2240	            limit,
2241	            sort_direction,
2242	            items_view,
2243	        } = params;
2244	        let items_view = items_view.unwrap_or(TurnItemsView::Summary);
2245	
2246	        let thread_uuid = ThreadId::from_string(&thread_id)
2247	            .map_err(|err| invalid_request(format!("invalid thread id: {err}")))?;
2248	
2249	        let items = self
2250	            .load_thread_turns_list_history(thread_uuid)
2251	            .await
2252	            .map_err(thread_read_view_error)?;
2253	        // This API optimizes network transfer by letting clients page through a
2254	        // thread's turns incrementally, but it still replays the entire rollout on
2255	        // every request. Rollback and compaction events can change earlier turns, so
2256	        // the server has to rebuild the full turn list until turn metadata is indexed
2257	        // separately.
2258	        let loaded_thread = self.thread_manager.get_thread(thread_uuid).await.ok();
2259	        let has_live_running_thread = match loaded_thread.as_ref() {
2260	            Some(thread) => matches!(thread.agent_status().await, AgentStatus::Running),
2261	            None => false,
2262	        };
2263	        let active_turn = if loaded_thread.is_some() {
2264	            // Persisted history may not yet include the currently running turn. The
2265	            // app-server listener has already projected live turn events into ThreadState,
2266	            // so merge that in-memory snapshot before paginating.
2267	            let thread_state = self.thread_state_manager.thread_state(thread_uuid).await;
2268	            let state = thread_state.lock().await;
2269	            state.active_turn_snapshot()
2270	        } else {
2271	            None
2272	        };
2273	        let mut turns = reconstruct_thread_turns_for_turns_list(
2274	            &items,
2275	            self.thread_watch_manager
2276	                .loaded_status_for_thread(&thread_uuid.to_string())
2277	                .await,
2278	            has_live_running_thread,
2279	            active_turn,
2280	        );
2281	        for turn in &mut turns {
2282	            match items_view {
2283	                TurnItemsView::NotLoaded => {
2284	                    turn.items.clear();
2285	                    turn.items_view = TurnItemsView::NotLoaded;
2286	                }
2287	                TurnItemsView::Summary => {
2288	                    let first_user_message = turn
2289	                        .items
2290	                        .iter()
2291	                        .find(|item| matches!(item, ThreadItem::UserMessage { .. }))
2292	                        .cloned();
2293	                    let final_agent_message = turn
2294	                        .items
2295	                        .iter()
2296	                        .rev()
2297	                        .find(|item| matches!(item, ThreadItem::AgentMessage { .. }))
2298	                        .cloned();
2299	                    turn.items = match (first_user_message, final_agent_message) {
2300	                        (Some(user_message), Some(agent_message))
2301	                            if user_message.id() != agent_message.id() =>
2302	                        {
2303	                            vec![user_message, agent_message]
2304	                        }
2305	                        (Some(user_message), _) => vec![user_message],
2306	                        (None, Some(agent_message)) => vec![agent_message],
2307	                        (None, None) => Vec::new(),
2308	                    };
2309	                    turn.items_view = TurnItemsView::Summary;
2310	                }
2311	                TurnItemsView::Full => {
2312	                    turn.items_view = TurnItemsView::Full;
2313	                }
2314	            }
2315	        }
2316	        let page = paginate_thread_turns(
2317	            turns,
2318	            cursor.as_deref(),
2319	            limit,
2320	            sort_direction.unwrap_or(SortDirection::Desc),
2321	        )?;
2322	        Ok(ThreadTurnsListResponse {
2323	            data: page.turns,
2324	            next_cursor: page.next_cursor,
2325	            backwards_cursor: page.backwards_cursor,
2326	        })
2327	    }
