2451	    async fn thread_resume_inner(
2452	        &self,
2453	        request_id: ConnectionRequestId,
2454	        params: ThreadResumeParams,
2455	        app_server_client_name: Option<String>,
2456	        app_server_client_version: Option<String>,
2457	    ) -> Result<(), JSONRPCErrorError> {
2458	        if let Ok(thread_id) = ThreadId::from_string(&params.thread_id)
2459	            && self
2460	                .pending_thread_unloads
2461	                .lock()
2462	                .await
2463	                .contains(&thread_id)
2464	        {
2465	            self.outgoing
2466	                .send_error(
2467	                    request_id,
2468	                    invalid_request(format!(
2469	                        "thread {thread_id} is closing; retry thread/resume after the thread is closed"
2470	                    )),
2471	                )
2472	                .await;
2473	            return Ok(());
2474	        }
2475	
2476	        if params.sandbox.is_some() && params.permissions.is_some() {
2477	            self.outgoing
2478	                .send_error(
2479	                    request_id,
2480	                    invalid_request("`permissions` cannot be combined with `sandbox`"),
2481	                )
2482	                .await;
2483	            return Ok(());
2484	        }
2485	        if params.persist_extended_history {
2486	            self.send_persist_extended_history_deprecation_notice(request_id.connection_id)
2487	                .await;
2488	        }
2489	        let redact_resume_payloads =
2490	            should_redact_thread_resume_payloads(app_server_client_name.as_deref());
2491	
2492	        let _thread_list_state_permit = match self.acquire_thread_list_state_permit().await {
