2767	        let running_thread = if params.history.is_some() {
2768	            if let Ok(existing_thread_id) = ThreadId::from_string(&params.thread_id)
2769	                && self
2770	                    .thread_manager
2771	                    .get_thread(existing_thread_id)
2772	                    .await
2773	                    .is_ok()
2774	            {
2775	                return Err(invalid_request(format!(
2776	                    "cannot resume thread {existing_thread_id} with history while it is already running"
2777	                )));
2778	            }
2779	            None
2780	        } else if let Ok(existing_thread_id) = ThreadId::from_string(&params.thread_id)
2781	            && let Ok(existing_thread) = self.thread_manager.get_thread(existing_thread_id).await
2782	        {
2783	            let source_thread = self
2784	                .read_stored_thread_for_resume(
2785	                    &params.thread_id,
2786	                    /*path*/ None,
2787	                    /*include_history*/ true,
2788	                )
2789	                .await?;
2790	            Some((existing_thread_id, existing_thread, source_thread))
2791	        } else {
2792	            let source_thread = self
2793	                .read_stored_thread_for_resume(
2794	                    &params.thread_id,
2795	                    params.path.as_ref(),
2796	                    /*include_history*/ true,
2797	                )
2798	                .await?;
2799	            let existing_thread_id = source_thread.thread_id;
2800	            match self.thread_manager.get_thread(existing_thread_id).await {
2801	                Ok(existing_thread) => Some((existing_thread_id, existing_thread, source_thread)),
2802	                Err(_) => None,
2803	            }
2804	        };
2805	
2806	        if let Some((existing_thread_id, existing_thread, source_thread)) = running_thread {
2807	            let existing_thread_rollout_path = existing_thread.rollout_path();
2808	            let active_path = existing_thread_rollout_path
2809	                .as_ref()
2810	                .or(source_thread.rollout_path.as_ref());
2811	            if let (Some(requested_path), Some(active_path)) = (params.path.as_ref(), active_path)
2812	                && requested_path != active_path
2813	            {
2814	                return Err(invalid_request(format!(
2815	                    "cannot resume running thread {existing_thread_id} with stale path: requested `{}`, active `{}`",
2816	                    requested_path.display(),
2817	                    active_path.display()
2818	                )));
2819	            }
2820	            let config_snapshot = existing_thread.config_snapshot().await;
2821	            let mismatch_details = collect_resume_override_mismatches(params, &config_snapshot);
2822	            if !mismatch_details.is_empty() {
2823	                let has_subscribers = !self
2824	                    .thread_state_manager
2825	                    .subscribed_connection_ids(existing_thread_id)
2826	                    .await
2827	                    .is_empty();
