2829	                    .thread_watch_manager
2830	                    .loaded_status_for_thread(&existing_thread_id.to_string())
2831	                    .await;
2832	                let is_running =
2833	                    matches!(existing_thread.agent_status().await, AgentStatus::Running);
2834	
2835	                if !has_subscribers && matches!(loaded_status, ThreadStatus::Idle) && !is_running {
