2840	                        ThreadShutdownResult::Complete => {
2841	                            self.thread_manager.remove_thread(&existing_thread_id).await;
2842	                            self.finalize_thread_teardown(existing_thread_id).await;
2843	                            return Ok(false);
2844	                        }
2845	                        ThreadShutdownResult::SubmitFailed => {
2846	                            warn!("failed to submit Shutdown to thread {existing_thread_id}");
2847	                        }
2848	                        ThreadShutdownResult::TimedOut => {
2849	                            warn!("thread {existing_thread_id} shutdown timed out");
2850	                        }
2851	                    }
2852	                }
2853	
2854	                // Preserve rejoin semantics when another client can still observe
2855	                // the loaded thread or shutdown did not complete.
2856	                tracing::warn!(
2857	                    "thread/resume overrides ignored for loaded thread {}: {}",
2858	                    existing_thread_id,
2859	                    mismatch_details.join("; ")
2860	                );
2861	            }
2862	            let redact_resume_payloads =
2863	                should_redact_thread_resume_payloads(app_server_client_name.as_deref());
2864	            let history_items = source_thread
2865	                .history
2866	                .as_ref()
2867	                .map(|history| history.items.clone())
2868	                .ok_or_else(|| {
2869	                    internal_error(format!(
2870	                        "thread {existing_thread_id} did not include persisted history"
2871	                    ))
2872	                })?;
2873	
2874	            let thread_state = self
2875	                .thread_state_manager
2876	                .thread_state(existing_thread_id)
2877	                .await;
