2880	                existing_thread.clone(),
2881	                thread_state.clone(),
2882	            )
2883	            .await?;
2884	            Self::set_app_server_client_info(
2885	                existing_thread.as_ref(),
2886	                app_server_client_name,
2887	                app_server_client_version,
2888	            )
2889	            .await?;
2890	
2891	            let mut summary_source_thread = source_thread;
2892	            summary_source_thread.history = None;
2893	            let mut thread_summary = self.stored_thread_to_api_thread(
2894	                summary_source_thread,
