2896	                /*include_turns*/ false,
2897	            );
2898	            thread_summary.session_id = existing_thread.session_configured().session_id.to_string();
2899	            let mut config_for_instruction_sources = self.config.as_ref().clone();
2900	            config_for_instruction_sources.cwd = config_snapshot.cwd.clone();
2901	            let instruction_sources =
2902	                Self::instruction_sources_from_config(&config_for_instruction_sources).await;
2903	
2904	            let listener_command_tx = {
2905	                let thread_state = thread_state.lock().await;
2906	                thread_state.listener_command_tx()
2907	            };
2908	            let Some(listener_command_tx) = listener_command_tx else {
2909	                return Err(internal_error(format!(
2910	                    "failed to enqueue running thread resume for thread {existing_thread_id}: thread listener is not running"
2911	                )));
2912	            };
2913	
2914	            let (emit_thread_goal_update, thread_goal_state_db) = self
2915	                .thread_goal_processor
2916	                .pending_resume_goal_state(existing_thread.as_ref())
2917	                .await;
2918	
2919	            let command = crate::thread_state::ThreadListenerCommand::SendThreadResumeResponse(
2920	                Box::new(crate::thread_state::PendingThreadResumeRequest {
2921	                    request_id: request_id.clone(),
2922	                    history_items,
2923	                    config_snapshot,
2924	                    instruction_sources,
2925	                    thread_summary,
2926	                    emit_thread_goal_update,
